n foreignThinkingOf(\n  context: Context,\n  identity: string = WORKBUDDY_MODEL_IDENTITY,\n  requestModelId?: string,\n): ForeignThinkingBlock[] {\n  const messages = (context as { messages?: unknown }).messages\n  if (!Array.isArray(messages)) return []\n  const found: ForeignThinkingBlock[] = []\n  for (const [messageIndex, message] of messages.entries()) {\n    if (!isForeignAssistant(message, identity, requestModelId)) continue\n    const record = message as Record<string, unknown>\n    const stopReason = record['stopReason']\n    // Mirrors `transform-messages.js`: an errored or aborted turn is skipped\n    // wholesale, so its blocks would not have surfaced either way.\n    const variant = stopReason === 'error' || stopReason === 'aborted' ? 'dropped' : 'flattened'\n    for (const [blockIndex, block] of blocksOf(message).entries()) {\n      if (typeof block !== 'object' || block === null) continue\n      const fields = block as Record<string, unknown>\n      if (fields['type'] !== 'thinking') continue\n      // A REDACTED block is never shown as prose: pi-ai returns `[]` for it\n      // (`:75–77`), so it is neither a leak nor a context cost worth naming.\n      if (fields['redacted'] === true) continue\n      const thinking = fields['thinking']\n      const characters = typeof thinking === 'string' ? thinking.length : 0\n      // Empty reasoning is dropped before any of the branches that matter\n      // (`:83–84`), so reporting it would be a false positive.\n      if (characters === 0) continue\n      found.push({ messageIndex, blockIndex, characters, variant })\n    }\n  }\n  return found\n}\n\n/**\n * EVERY thinking block in the transcript, whoever produced it (issue #213).\n *\n * The narrow repairs above (`foreignThinkingOf`, `crossProviderThinkingOf`) exist\n * so a different model's reasoning is never replayed as this one's. This one\n * answers a different question: the WorkBuddy CHANNEL GATE scans the request\n * text, and a reporter matched every banned opening in a 11128 failure against\n * the session log's `reasoning` blocks character for character. The gate reads\n * what we send, and one of the things we send is our own past reasoning\n * (`reasoning_content`, emitted whenever a thinking block carries a signature).\n *\n * So this is not a repair of a mislabelled turn — it is a REDACTION, and it is\n * why it is a user switch rather than a default: dropping the model's own\n * reasoning from history changes what the model can see about its earlier work,\n * which is a real cost paid to get past the gate. The official client's history\n * very likely carries no thinking text at all, which is the reporter's point and\n * the reason this is worth offering.\n *\n * `variant` is 'flattened' for every block, and that is an APPROXIMATION this\n * function cannot refine: the real outcome depends on the block's signature,\n * which only pi-ai's request builder can see.\n *\n *   - a block whose `thinkingSignature` is one of the three reasoning field names\n *     is REPLAYED as that field (`reasoning_content` for this vendor), not\n *     flattened;\n *   - a block with NO signature is never emitted at all - it is dropped from the\n *     request, not turned into prose;\n *   - a block whose message fails `isSameModel` IS flattened into assistant prose\n *     (`transform-messages.js`, the `isSameModel` else-branch), and that is the\n *     only real 'flattened' case — up to pi-ai 1.2. From 1.3 such a block is\n *     discarded instead, which moves it into the second bullet's outcome.\n *\n * So the field is deliberately not surfaced to the user: `variant` reaches\n * nothing but the diagnostic callback, and a label that is wrong for two of the\n * three cases would mislead whoever finally does display it. The count is what\n * the user is told (\"N blocks were removed\"), which is true for all three.\n */\nexport function allThinkingOf(context: Context): ForeignThinkingBlock[] {\n  const messages = (context as { messages?: unknown }).messages\n  if (!Array.isArray(messages)) return []\n  const found: ForeignThinkingBlock[] = []\n  for (const [messageIndex, message] of messages.entries()) {\n    for (const [blockIndex, block] of blocksOf(message).entries()) {\n      if (typeof block !== 'object' || block === null) continue\n      const fields = block as Record<string, unknown>\n      if (fields['type'] !== 'thinking') continue\n      if (fields['redacted'] === true) continue\n      const thinking = fields['thinking']\n      const characters = typeof thinking === 'string' ? thinking.length : 0\n      if (characters === 0) continue\n      found.push({ messageIndex, blockIndex, characters, variant: 'flattened' })\n    }\n  }\n  return found\n}\n\n/**\n * The subset of {@link foreignThinkingOf} that is safe to repair without asking.\n *\n * This is the predicate the adapter uses when `dropForeignThinking` is OFF: a\n * turn from another provider/route is dropped unconditionally, because its\n * unsigned thinking block can never be replayed and its flattened prose is what\n * the WorkBuddy gateway refuses (issue #163's provider-switch scene). A turn\n * from this bundle under a different model id is NOT included — that one is\n * still the explicit switch's business.\n *\n * Runs after `alignAssistantIdentities`, so a global-region turn this bundle\n * owns has already had its `dsh-foreign` marker repaired away and is not\n * misclassified.\n */\nexport function crossProviderThinkingOf(\n  context: Context,\n  identity: string = WORKBUDDY_MODEL_IDENTITY,\n  ownedRoutes: readonly string[] = [WORKBUDDY_PROVIDER, WORKBUDDY_GLOBAL_PROVIDER],\n): ForeignThinkingBlock[] {\n  const messages = (context as { messages?: unknown }).messages\n  if (!Array.isArray(messages)) return []\n  return foreignThinkingOf(context, identity).filter(block =>\n    isCrossProviderAssistant(messages[block.messageIndex], identity, ownedRoutes))\n}\n\n/**\n * Remove the foreign thinking blocks {@link foreignThinkingOf} finds.\n *\n * WHY REMOVAL IS THE HONEST REPAIR. The alternatives are both worse:\n *\n *   - LEAVE IT: pi-ai publishes the other provider's private working notes as\n *     this turn's answer (the #147 defect), so the user reads reasoning instead\n *     of a reply and the model imitates that shape forever after.\n *   - KEEP IT AS THINKING: impossible from here. `isSameModel` is pi-ai's own\n *     predicate over fields this plugin does not control (`model.provider` /\n *     `model.api` / `model.id` are compared against the MESSAGE's), and the\n *     only way to satisfy it is to claim the foreign turn as this model's own\n *     output — which is exactly the provenance lie issue #111 removed. These\n *     blocks carry no `thinkingSignature` (the host builds them that way), so\n *     they could not be replayed as signed reasoning even if claimed.\n *\n * Dropping is what the request builder already does with them in every other\n * branch: an unsigned foreign thinking block is never sent as\n * `reasoning_content`, so its only possible contribution to the wire was the\n * flattened prose this function removes. Every other block — text, tool calls —\n * is left exactly where it is, and so is every message's identity.\n *\n * Idempotent: a second pass finds nothing to remove. Returns the SAME context\n * object when nothing changed, so the common case allocates nothing.\n *\n * @param context - a pi-ai context.\n * @param identity - the identity this adapter stamps on its own models.\n * @param requestModelId - model id the request is addressed to (see\n *   {@link isForeignAssistant}); omitted, only the provider/api legs are judged.\n * @returns the repaired context, or the input when no block qualified.\n */\nexport function dropForeignThinking(\n  context: Context,\n  identity: string = WORKBUDDY_MODEL_IDENTITY,\n  requestModelId?: string,\n): Context {\n  return dropThinkingBlocks(context, foreignThinkingOf(context, identity, requestModelId))\n}\n\n/** Remove exactly the listed blocks; the one place that edits a transcript. */\nfunction dropThinkingBlocks(context: Context, affected: readonly ForeignThinkingBlock[]): Context {\n  if (affected.length === 0) return context\n  const messages = (context as unknown as { messages: unknown[] }).messages\n  // Group by message first: each message is copied at most once, and a message\n  // whose content becomes empty is left in place (pi-ai drops it anyway; moving\n  // it here would renumber tool-result pairing for no benefit).\n  const byMessage = new Map<number, Set<number>>()\n  for (const block of affected) {\n    const set = byMessage.get(block.messageIndex) ?? new Set<number>()\n    set.add(block.blockIndex)\n    byMessage.set(block.messageIndex, set)\n  }\n  const next = messages.map((message, index) => {\n    const remove = byMessage.get(index)\n    if (remove === undefined) return message\n    const record = message as Record<string, unknown>\n    const content = blocksOf(message).filter((_, blockIndex) => !remove.has(blockIndex))\n    return { ...record, content }\n  })\n  return { ...context, messages: next } as Context\n}\n\n/**\n * How deeply this wrapper repairs the transcript before it reaches pi-ai.\n *\n * Both members are OFF by default, so a config that never mentions them sends\n * byte-for-byte what earlier builds sent (see {@link WorkBuddyAdapterOptions}).\n */\nexport interface TranscriptRepairOptions {\n  /**\n   * Drop SAME-ROUTE foreign thinking blocks pi-ai would publish as prose\n   * (issue #147). `false` keeps the previous behaviour for a model switch\n   * inside one route.\n   *\n   * Cross-provider turns are repaired regardless of this switch (issue #163's\n   * provider-switch scene): their unsigned thinking blocks can never be\n   * replayed, and their flattened prose is what the gateway refuses.\n   */\n  dropForeignThinking?: boolean\n  /**\n   * Drop EVERY historical thinking block, including this model's own (issue #213).\n   *\n   * Wider than `dropForeignThinking` and answers a different question: that one\n   * repairs a turn whose provenance is wrong, this one REDACTES text the channel\n   * gate scans. `true` supersedes it.\n   */\n  dropAllThinking?: boolean\n  /**\n   * Told how many blocks that repair removed and where, so a surface can name\n   * the condition the user is actually looking at. Called at most once per\n   * request, and only when something was removed.\n   */\n  onForeignThinking?: (blocks: readonly ForeignThinkingBlock[]) => void\n}\n\n/**\n * Pick the repair this request needs and apply it.\n *\n * EXTRACTED so the choice itself is testable. When the selection lived inline in\n * `prepare`, the only thing a test could assert was what each PREDICATE returns —\n * and a mutation that deleted the `dropAllThinking` branch entirely still left\n * every test green, because no test ever asked \"which predicate ran\". That is a\n * decoration, not a guard (AGENTS.md: a test that stays green when you break the\n * code is not a test).\n *\n * The order is load-bearing: `dropAllThinking` is checked FIRST because it is the\n * broadest. A user who turned it on has decided the gate matters more than the\n * model seeing its own past reasoning, so the narrow \"is this block foreign?\"\n * question is no longer the one to ask.\n */\nexport function applyTranscriptRepair(\n  context: Context,\n  repair?: TranscriptRepairOptions,\n  identity: string = WORKBUDDY_MODEL_IDENTITY,\n  requestModelId?: string,\n  ownedRoutes: readonly string[] = [WORKBUDDY_PROVIDER, WORKBUDDY_GLOBAL_PROVIDER],\n): Context {\n  const affected = repair?.dropAllThinking === true\n    ? allThinkingOf(context)\n    : repair?.dropForeignThinking === true\n      ? foreignThinkingOf(context, identity, requestModelId)\n      : crossProviderThinkingOf(context, identity, ownedRoutes)\n  if (affected.length === 0) return context\n  try {\n    repair?.onForeignThinking?.(affected)\n  } catch {\n    // A diagnostic must never fail a chat request.\n  }\n  return dropThinkingBlocks(context, affected)\n}\n\nfunction withLegacyContext(\n  api: ProviderStreams,\n  generation: PiAiGeneration,\n  identity: string = WORKBUDDY_MODEL_IDENTITY,\n  ownedRoutes: readonly string[] = [WORKBUDDY_PROVIDER, WORKBUDDY_GLOBAL_PROVIDER],\n  repair?: TranscriptRepairOptions,\n): ProviderStreams {\n  /** One place so both branches and both entry points agree on the order. */\n  const prepare = (context: Context, requestModelId?: string): Context => {\n    const folded = generation === 'modern' ? foldModernContext(context) : adaptLegacyPiAiContext(context)\n    const aligned = alignAssistantIdentities(folded, identity, ownedRoutes)\n    // ISSUE #147, AFTER alignment on purpose. `foreignThinkingOf` reads the\n    // identity to decide what is foreign, so running it first would classify a\n    // turn this plugin OWNS (route id still unaligned) as foreign and delete its\n    // reasoning — issue #102's regression, from the other direction.\n    //\n    // ISSUE #163: a CROSS-PROVIDER turn is repaired even when the switch is\n    // off. Its thinking block has no signature and can never be replayed, and\n    // pi-ai would otherwise flatten it into assistant prose — which is the\n    // content the WorkBuddy gateway refused in the measured provider-switch\n    // scene. The switch only widens this to a same-route model switch, whose\n    // turn this bundle did produce.\n    //\n    // `requestModelId` is pi-ai's third predicate leg. Without it a switch\n    // BETWEEN MODELS inside one region (`hy3` → `deepseek-v4.1-flash`, both on\n    // this route) degraded exactly like a cross-provider switch, while this\n    // repair saw nothing to do: provider and api both still matched.\n    // ISSUE #213 takes precedence over both repairs, and it is checked FIRST\n    // because it is the broadest: a user who turned it on has decided the gate\n    // matters more than the model seeing its own past reasoning, so the narrow\n    // \"is this block foreign?\" question is no longer the one to ask.\n    return applyTranscriptRepair(aligned, repair, identity, requestModelId, ownedRoutes)\n  }\n  if (generation === 'modern') {\n    return {\n      ...api,\n      stream: (model, context, options) =>\n        api.stream(model, transcript<Parameters<typeof api.stream>[1]>(prepare(context, model.id)), options),\n      streamSimple: (model, context, options) =>\n        api.streamSimple(\n          model,\n          transcript<Parameters<typeof api.streamSimple>[1]>(prepare(context, model.id)),\n          options,\n        ),\n    }\n  }\n  return {\n    ...api,\n    stream: (model, context, options) =>\n      api.stream(model, transcript<Parameters<typeof api.stream>[1]>(prepare(context, model.id)), options),\n    streamSimple: (model, context, options) =>\n      api.streamSimple(\n        model,\n        transcript<Parameters<typeof api.streamSimple>[1]>(prepare(context, model.id)),\n        options,\n      ),\n  }\n}\n\n/**\n * Which rescue, if any, an error event calls for (issue #258).\n *\n * ALL of an error message's text is searched, in the shapes pi-ai hands over:\n * `errorMessage` on the assistant message is the one that matters, but a\n * provider that fills only `content` or throws a bare string has been measured,\n * so the reader is deliberately tolerant. The scan never throws: a message with\n * no strings in it simply calls for no rescue.\n *\n * `'window'` wins when both readings somehow apply, because the token overflow\n * is the one this rescue was originally written for and its target is the more\n * conservative of the two.\n */\nexport function rescueCauseOf(error: AssistantMessage): RescueCause | undefined {\n  if (isContextOverflow(error)) return 'window'\n  const text = [\n    typeof error.errorMessage === 'string' ? error.errorMessage : '',\n    typeof error.content === 'string' ? error.content : '',\n    ...Array.isArray(error.content)\n      ? error.content.map(part => (typeof part === 'object' && part !== null\n        && typeof (part as { text?: unknown }).text === 'string'\n        ? (part as { text: string }).text\n        : ''))\n      : [],\n  ].join(' ')\n  return isBodyOversizeRefusal(text) ? 'body-bytes' : undefined\n}\n\n/**\n * Layer the host-side context-overflow rescue onto a provider's streams.\n *\n * pi-ai reports a provider failure as an `error` event rather than a throw, so\n * the rescue runs while the failing assistant message is still in hand: history\n * is folded before the event continues on its way, and the host's retry then\n * rebuilds its request against a smaller surface. Nothing is swallowed — the\n * error event is forwarded unchanged, because deciding whether to retry is the\n * host's policy, not this transport's.\n *\n * Both gates are deliberate. Without `sessionId` there is no session to fold,\n * and without a declared `contextWindow` there is no budget to fold against;\n * either absence leaves the stream untouched.\n */\nfunction withContextRescue(\n  api: ProviderStreams,\n  resolve: (() => ContextRescue | undefined) | undefined,\n): ProviderStreams {\n  if (resolve === undefined) return api\n\n  // Both parameters stay generic so this wrapper serves whichever pi-ai\n  // generation is installed: 1.x replaced the flat `Context` with a branded\n  // `TranscriptContext`, and naming either type here would pin the wrapper to\n  // one generation and break the other's typecheck.\n  const wrap = <ContextShape, Options>(\n    inner: (model: Model<Api>, context: ContextShape, options?: Options) => AssistantMessageEventStream,\n  ) =>\n    (model: Model<Api>, context: ContextShape, options?: Options): AssistantMessageEventStream => {\n      const source = inner(model, context, options)\n      const rescue = resolve()\n      // 0.85 and 1.x both carry the session id here under the same name; the\n      // structural read keeps the wrapper independent of the options type.\n      const sessionId = (options as { sessionId?: string } | undefined)?.sessionId\n      const window = model.contextWindow\n      if (rescue === undefined || sessionId === undefined || window === undefined) return source\n\n      const out = createAssistantMessageEventStream()\n      let final: AssistantMessage | undefined\n      void (async () => {\n        try {\n          for await (const event of source) {\n            if (event.type === 'done') final = event.message\n            if (event.type === 'error') final = event.error\n            // Fold before the consumer settles: the error still reaches it, but\n            // the surface is already smaller when the host retries.\n            //\n            // TWO causes, one rescue (issue #258). `isContextOverflow` only\n            // recognises TOKEN overflow, so a request refused because its body\n            // exceeded a byte ceiling reached this loop and matched nothing —\n            // the surface was never folded and every retry re-sent the same\n            // oversized body. The byte case is detected HERE as well, from the\n            // same message text, and folded with its own target because the two\n            // ceilings are measured in different units (tokens vs bytes).\n            if (event.type === 'error') {\n              const cause = rescueCauseOf(event.error)\n              if (cause !== undefined) await rescue.rescue(sessionId, window, cause)\n            }\n            out.push(event)\n          }\n          out.end(final)\n        } catch {\n          // Unreachable in practice: pi-ai converts every provider failure into\n          // an `error` event. Close the stream rather than leave a consumer\n          // waiting on an iterator that will never advance.\n          out.end(final)\n        }\n      })()\n      return out\n    }\n\n  return { ...api, stream: wrap(api.stream), streamSimple: wrap(api.streamSimple) }\n}\n\n/**\n * The tier {@link EffortNormalizingAdapter} pins a model to when the model\n * carries no reasoning metadata of its own.\n *\n * `off` is the ONE tier pi-ai offers for such a model (`getSupportedThinkingLevels`\n * returns `['off']` whenever `model.reasoning` is false), and the host's own\n * translation of it is \"send no reasoning field at all\" (`profileOptions` turns\n * `off` into `enabledReasoning = undefined`). So pinning it neither invents a\n * capability nor changes one byte of the upstream request body.\n */\nconst NO_REASONING_EFFORT = ReasoningEffortId('off')\n\n/** What the host is told a reasoning-less model supports: exactly that tier. */\nconst NO_REASONING_EFFORTS: LlmModelReasoningInfo = {\n  efforts: [{ id: NO_REASONING_EFFORT, name: 'Off' }],\n}\n\n/**\n * pi-ai adapter that keeps a model WITHOUT reasoning metadata dispatchable\n * (issue #90, the `UNSUPPORTED_REASONING_EFFORT` half).\n *\n * THE FAILURE. `profileFor` pins one default tier per ROUTE\n * (`reasoning: WORKBUDDY_DEFAULT_EFFORT`, issue #83), and `dsh-llm-pi-ai`\n * resolves every request as `options.reasoningEffort ?? profile.reasoning`. For\n * a model whose catalog entry carries no `reasoning` block at all — the live CN\n * catalog has six of them (`default`, `glm-5.0`, `glm-4.7`, `glm-4.6`,\n * `hunyuan-chat`, `hunyuan-image-alpha`), the live global one two\n * (`default-model`, `deep-model`), and EVERY entry of both static fallback lists\n * — the inherited `high` is not a tier that model has. (`default-model` is the\n * international `auto` router and is not offered as a row since 5.0.1; the\n * measurement is kept verbatim because the defect it documents was observed\n * against the full roster.) `resolveReasoningLevel`\n * then throws `UNSUPPORTED_REASONING_EFFORT` before the request is even built,\n * so the model is unusable locally: no wire call, no upstream error, nothing to\n * retry. Introduced by v4.11.0, which made the profile default explicit; before\n * it the default was absent and pi-ai clamped instead of throwing.\n *\n * TWO GATES, BOTH CLOSED. The host checks the adapter's own model metadata\n * first: `resolveCallWithInfo` rejects ANY explicitly requested tier on a model\n * whose `reasoning` is absent, and `reasoningInfo` omits the field exactly for\n * models without metadata — so even `off` was refused. Then `PiAiAdapter.streamWithSnapshot`\n * rejects the route default it inherited. A fix at either seam alone still\n * fails at the other.\n *\n * THE FIX. Advertise the one tier pi-ai will actually accept for such a model\n * (`off`) and normalize the request to it at the dispatch seam, so\n * `resolveReasoningLevel` sees a supported tier and `profileOptions` sends no\n * reasoning field. Nothing about the wire body changes — pi-ai never emits\n * `reasoning_effort` for a model whose descriptor has `reasoning: false`.\n *\n * WHAT STAYS STRICT. A tier the caller EXPLICITLY asks for on a model that\n * cannot do it is still rejected, by the host, with an accurate message. That\n * is the pre-v4.11.0 contract too, and it is not this bug: the bug is a request\n * that named no tier being killed by the route's own default.\n */\nclass EffortNormalizingAdapter extends PiAiAdapter {\n  /**\n   * Whether one exact model id currently carries reasoning metadata. Read live\n   * on every call because the catalog is refreshed behind the adapter\n   * (`invalidate`), and a model that gains metadata mid-session must stop being\n   * normalized at once.\n   */\n  private readonly effortCapable: (model: string) => boolean\n\n  /**\n   * The tier one exact model should advertise as its default when a caller\n   * names none (issue #179).\n   *\n   * Read LIVE per resolve/prepare call, like {@link effortCapable}: the user can\n   * change the choice mid-session, and `applySelection` re-invalidates the\n   * catalog on every settings change. A captured value would make the picker\n   * show the new default while requests kept the old one.\n   *\n   * Returns `undefined` for a model with no tier vocabulary — the caller then\n   * leaves the advertised `reasoning` block exactly as pi-ai built it, which is\n   * the `off`-only shape `advertiseOffOnly` below depends on.\n   */\n  private readonly defaultEffort: (model: string) => string | undefined\n\n  /**\n   * The selector badge for one exact model, or `undefined` when it carries none.\n   *\n   * Read LIVE on every `listModels()` call, like {@link effortCapable}: the\n   * answer depends on the clock (a night window opens and closes), and the host\n   * re-reads the catalog rather than caching this for the session.\n   *\n   * @see listModels for why the badge lives here at all.\n   */\n  private readonly modelBadge: (model: string) => LlmModelBadge | undefined\n\n  constructor(\n    config: PiAiAdapterOptions,\n    effortCapable: (model: string) => boolean,\n    defaultEffort: (model: string) => string | undefined = () => undefined,\n    modelBadge: (model: string) => LlmModelBadge | undefined = () => undefined,\n  ) {\n    super(config)\n    this.effortCapable = effortCapable\n    this.defaultEffort = defaultEffort\n    this.modelBadge = modelBadge\n  }\n\n  /**\n   * The catalog, with this plugin's selector badge attached to each model.\n   *\n   * WHY THIS OVERRIDE EXISTS (issue #138). `conversation.input.model.label` is a\n   * `single` slot, so whichever plugin wins it draws EVERY provider's rows — and\n   * the host's own badge fallback only runs when the cell has NO occupant. A\n   * sibling's chip therefore survives only if it travels as DATA rather than as\n   * a component. From 0.2.2 the host's directory carries exactly such a field\n   * (`LlmModelInfo.badge`), and the only way an adapter can fill it is here:\n   * `resolveModel()` is normalized by the registry, which drops `badge`, so a\n   * value returned from there never reaches the picker.\n   *\n   * WHY THE SPREAD AND NOT AN OBJECT LITERAL. This plugin's peer range still\n   * starts at `0.1.7-rc.1`, where `LlmModelInfo` has no `badge` field — an\n   * object literal naming it would fail to compile against that declaration.\n   * The spread compiles against both, and on 0.1.x the extra property is simply\n   * not read by anything. No runtime version check is needed or wanted.\n   *\n   * WHAT IS DELIBERATELY NOT HERE: the live load level. A catalog refresh costs\n   * one `resolveModelInfo()` per model, so a per-minute fact would have to be\n   * republished by emitting `llm/models-updated` on every probe — and a stale\n   * 🚦 is worse than no 🚦. The load level stays on this plugin's own rows,\n   * where the component can re-read a snapshot per render.\n   */\n  override async listModels(provider: string): Promise<LlmModelInfo[]> {\n    const models = await super.listModels(provider)\n    return models.map((model) => {\n      const badge = this.modelBadge(model.id)\n      return { ...model, ...badge === undefined ? {} : { badge } }\n    })\n  }\n\n  override async resolveModel(provider: string, model: string, signal?: AbortSignal): Promise<LlmResolvedModelInfo> {\n    return this.advertiseDefaultEffort(this.advertiseOffOnly(await super.resolveModel(provider, model, signal)))\n  }\n\n  override async prepareCall(provider: string, model: string, signal?: AbortSignal): Promise<PreparedAdapterCall> {\n    const call = await super.prepareCall(provider, model, signal)\n    // Both halves matter: the host validates `model` before it ever calls\n    // `stream`, and `stream` is what actually reaches `resolveReasoningLevel`.\n    return {\n      model: this.advertiseDefaultEffort(this.advertiseOffOnly(call.model)),\n      stream: (options: GenerateOptions): AsyncIterable<StreamChunk> => call.stream(this.pinEffort(options)),\n    }\n  }\n\n  override stream(options: GenerateOptions): AsyncIterable<StreamChunk> {\n    return super.stream(this.pinEffort(options))\n  }\n\n  /**\n   * Advertise the per-model default tier (issue #179).\n   *\n   * The host materializes `reasoningEffort` into EVERY request that names none\n   * from this exact field (`LlmRuntime.resolveCallWithInfo`), which is what makes\n   * a saved per-model default real rather than a display preference: without\n   * `defaultEffort` the host leaves the config field empty and pi-ai falls back\n   * to `profile.reasoning` — the one route-wide constant this feature exists to\n   * replace.\n   *\n   * Deliberately a no-op when the model declares no tier: pi-ai's `off`-only\n   * block must keep its EXACT advertised shape, or the host's prepared-call\n   * config check (`callConfigEquals`) starts disagreeing with callers that omit\n   * the field — see `advertiseOffOnly` above.\n   */\n  private advertiseDefaultEffort(info: LlmResolvedModelInfo): LlmResolvedModelInfo {\n    if (info.reasoning === undefined) return info\n    const effort = this.defaultEffort(info.id)\n    if (effort === undefined) return info\n    // Never contradict the tier list: an entry the host would reject is worse\n    // than no default at all (issue #90's `UNSUPPORTED_REASONING_EFFORT`).\n    if (!info.reasoning.efforts.some(level => level.id === effort)) return info\n    if (info.reasoning.defaultEffort === effort) return info\n    return {\n      ...info,\n      reasoning: { ...info.reasoning, defaultEffort: ReasoningEffortId(effort) },\n    }\n  }\n\n  /**\n   * Give a reasoning-less model the one tier it can dispatch at. No\n   * `defaultEffort` on purpose: the host materializes one into EVERY request\n   * that names no tier, and that would turn the host's own prepared-call config\n   * check (`callConfigEquals`) against callers that omit the field.\n   */\n  private advertiseOffOnly(info: LlmResolvedModelInfo): LlmResolvedModelInfo {\n    return info.reasoning === undefined ? { ...info, reasoning: NO_REASONING_EFFORTS } : info\n  }\n\n  /** Replace an unusable tier with the one pi-ai accepts for this model. */\n  private pinEffort(options: GenerateOptions): GenerateOptions {\n    if (this.effortCapable(options.model)) return options\n    return options.reasoningEffort === NO_REASONING_EFFORT\n      ? options\n      : { ...options, reasoningEffort: NO_REASONING_EFFORT }\n  }\n}\n\n/**\n * Assemble the adapter. The provider's `getModels` reads the live catalog,\n * and every model's `baseUrl` is re-resolved per read so the shim's\n * ephemeral port applies from the first snapshot after startup.\n */\nexport function createWorkBuddyAdapter(options: WorkBuddyAdapterOptions): WorkBuddyAdapter {\n  const { shim, store, catalog, resolveAttachments } = options\n  const providerId = options.provider ?? WORKBUDDY_PROVIDER\n  const providerName = options.displayName ?? 'WorkBuddy'\n  // The model identity is shared by both regions on purpose — that is the whole\n  // of issue #59's fix, and it is NOT inert (issue #75): `requireProvider` and\n  // `getAuth` resolve the registry BY the stamped `model.provider`. The route\n  // id below is NOT shared: it keys the registry a user selects from, and each\n  // region's route resolves to that region's own shim. So the identity is\n  // published as an EXTRA registry key of the same route (see\n  // `modelIdentityKeysOf`) instead of replacing the route id — the two halves\n  // of #59 and #75 that way stay true at once.\n  const modelIdentity = options.modelIdentity ?? WORKBUDDY_MODEL_IDENTITY\n  // The generation gate: what THIS plugin resolves, not what the host runs —\n  // a nested 0.85 on disk shadows the host's 0.87 and vice versa, and only\n  // the resolved copy decides which context shape the api below can consume.\n  const generation = options.piAiGeneration ?? piAiRuntimeInfo().generation\n  void store\n\n  const buildModels = (): Model<Api>[] => {\n    // The OpenAI SDK pi-ai drives appends `/chat/completions` to baseURL,\n    // so the shim's routes line up with the `/v1` prefix in place.\n    const baseUrl = `${shim.baseUrl()}/v1`\n    // The `in-history` capability travels with the ROUTE, not the model: which\n    // upstream answers is a property of the route, and the two gateways are\n    // separate services with separate behaviour. Only the CN one has been\n    // measured to obey a `system` message placed after the history, so the\n    // international route keeps the pre-existing shape. An unrecognised route id\n    // (a test passing a literal, a future region) gets the conservative default.\n    const midConvoSystemMessages = regionOfProvider(providerId) === 'cn'\n    // Route B is read LIVE here so flipping the card can rebuild the model\n    // shape on the next `getModels`/catalog read without a plugin reload.\n    const sessionAffinity = options.sessionConversationId?.() === true\n    return catalog.current().map(info => toPiModel(info, baseUrl, modelIdentity, midConvoSystemMessages, sessionAffinity))\n  }\n\n  const base = createProvider({\n    id: providerId,\n    name: providerName,\n    auth: {\n      apiKey: {\n        name: 'WorkBuddy OAuth bearer token',\n        async resolve({ credential }) {\n          const apiKey = credential?.key\n          return apiKey === undefined || apiKey.length === 0\n            ? undefined\n            : { auth: { apiKey }, source: 'WorkBuddy' }\n        },\n      },\n    },\n    models: buildModels(),\n    api: withContextRescue(\n      // BOTH of this bundle's routes are owned by this adapter, so a message\n      // stamped with either is ours to align (issue #111). Anything else in\n      // the transcript belongs to another provider and is left untouched.\n      withLegacyContext(openAICompletionsApi(), generation, modelIdentity, undefined, {\n        // Both read per request: the switch is meant to be flipped WHILE\n        // looking at the bad turn, and a captured boolean would need a reload.\n        get dropForeignThinking() { return options.dropForeignThinking?.() === true },\n        get dropAllThinking() { return options.dropAllThinking?.() === true },\n        ...options.onForeignThinking === undefined ? {} : { onForeignThinking: options.onForeignThinking },\n      }),\n      options.resolveContextRescue,\n    ),\n  })\n\n  // `getModels` is delegated to a live read (the reuse-catalog pattern from\n  // dsh-llm-pi-ai): stream dispatch still runs through the constructed\n  // provider, while the catalog answer tracks the upstream refresh.\n  const provider: Provider = { ...base, getModels: () => buildModels() }\n\n  // One profile per published registry key. The `piProvider` is what actually\n  // lands in the registry, and `Models.setProvider` keys that map on\n  // `piProvider.id` (`models.js:37` on 0.85.1, `:49` on 1.1.0) — NOT on the\n  // profile's `provider` field — so the identity key needs a provider object\n  // that CLAIMS that id. It is the route's own provider under a second id, so\n  // the models, baseUrl, api and auth the request runs with stay this region's\n  // and nothing about the gateway is duplicated. Sharing the very same object\n  // under both keys would register the route id twice and leave the stamped\n  // identity unresolved, which is exactly issue #75.\n  const profileFor = (key: string): ResolvedPiAiProviderProfile => ({\n    provider: key,\n    displayName: providerName,\n    streamIdleTimeoutMs: WORKBUDDY_STREAM_IDLE_TIMEOUT_MS,\n    retryPolicy: resolveRetryPolicy(undefined, 'dsh-connect-workbuddy retryPolicy'),\n    configuredMaxTokens: new Map(),\n    // Per-model failures gate every request: `modelOf` throws INVALID_CONFIG\n    // for any id present here. The workbuddy catalog is built from live reads,\n    // so an empty map is the accurate answer — no known-bad model — and the\n    // route must never pre-condemn a model that the catalog later supplies.\n    // (Required by ResolvedPiAiProviderProfile since 0.1.5-rc.1.)\n    modelErrors: new Map(),\n    /**\n     * The ROUTE-WIDE fallback tier, pinned to the SAME value pi-ai's level map\n     * would fill in for an absent one (issue #83).\n     *\n     * `dsh-llm-pi-ai` resolves every request's tier as\n     * `options.reasoningEffort ?? profile.reasoning`, so an absent default here\n     * means \"whatever pi-ai fills in\" — and for a model whose map carried\n     * `off → \"off\"`, that was `\"off\"`, i.e. every compaction summary asked a\n     * model like `deepseek-v4.1-flash` to disable thinking, which it answers with\n     * 400 / 11133. Nothing structurally prevents a level or a catalog snapshot\n     * from disagreeing with the adapter's own map, so the default must never be\n     * that.\n     *\n     * Since issue #179 this is only the LAST resort: `advertiseDefaultEffort`\n     * publishes the user's per-MODEL choice as `defaultEffort`, and the host\n     * materializes that into every request that names none — so a user who\n     * picked `low` for one model gets `low` while every other model keeps its own\n     * upstream default. This constant survives for a model whose catalog entry\n     * declares no default at all, which is the only case that reaches here.\n     */\n    reasoning: WORKBUDDY_DEFAULT_EFFORT,\n    ...REQUEST_IMAGE_BUDGETS,\n    piProvider: key === providerId ? provider : { ...provider, id: key },\n  })\n\n  // Single source for BOTH the initial map and `invalidate`: an `invalidate`\n  // that rebuilt only the route key would silently re-break the identity key,\n  // i.e. issue #75 all over again on the first catalog refresh.\n  const buildProfiles = (): Map<string, ResolvedPiAiProviderProfile> =>\n    new Map(modelIdentityKeysOf(providerId, modelIdentity)\n      .map((key): [string, ResolvedPiAiProviderProfile] => [key, profileFor(key)]))\n\n  // Replacing (not mutating) the map is what `invalidate` uses to force the\n  // adapter's next profiles read to rebuild its snapshot.\n  let profiles = buildProfiles()\n\n  /**\n   * Whether one exact model id currently advertises ANY thinking tier.\n   *\n   * Same predicate `toPiModel` derives the descriptor's `reasoning` flag from,\n   * so the two can never disagree — and it reads the live catalog, so a refresh\n   * that adds (or drops) metadata for a model takes effect on the next request\n   * without an `invalidate` round trip.\n   */\n  const effortCapable = (model: string): boolean =>\n    catalog.current().some(info => info.id === model && workBuddyThinkingLevelMap(info) !== undefined)\n\n  /**\n   * The tier one exact model should run on when a caller names none (#179).\n   *\n   * Resolved against the LIVE catalog and the user's LIVE saved map, exactly\n   * like `effortCapable`: the answer is a function of two things that both\n   * change mid-session, and caching either would let the advertised default and\n   * the dispatched tier drift apart.\n   */\n  const resolveDefaultEffort = (model: string): string | undefined => {\n    const info = catalog.current().find(entry => entry.id === model)\n    if (info === undefined) return undefined\n    return defaultEffortFor(info, options.defaultThinkingEfforts?.() ?? {})\n  }\n\n  /**\n   * The selector badge for one model: whatever promotion holds RIGHT NOW.\n   *\n   * WHY THE CLOCK IS READ HERE. `promos` rides along UNRESOLVED on the model\n   * entry precisely so the decision can be made where it is drawn (`src/promo.ts`\n   * explains why freezing it at parse time would leave \"夜间折扣\" on the row the\n   * next morning). `listModels()` is called when the host builds the catalog, so\n   * this is that \"where it is drawn\" moment on the host side.\n   *\n   * WHY A TABLE, AND WHEN IT COLLAPSES TO A STRING. The host resolves\n   * `badge.text` against the READER's locale (`ctx.locale.resolveText`), and this\n   * function runs in the host process, where the browser's language is not\n   * knowable. A table lets the host pick; a bare string forces one language on\n   * every user. `en` is mandatory in a table — one without it resolves to\n   * `undefined` and the chip disappears entirely.\n   *\n   * Most CN promotions publish NO English wording, so `en = labelEn ?? label`\n   * makes both entries identical and the value collapses to a bare string. That\n   * is deliberate: inventing English copy would be worse than showing the\n   * upstream's own Chinese wording to an English reader.\n   *\n   * ONLY THE PROMOTION GOES IN. The load level is a per-minute fact; see\n   * `listModels` for why it deliberately stays on this plugin's own rows.\n   */\n  const resolveModelBadge = (model: string): LlmModelBadge | undefined => {\n    const info = catalog.current().find(entry => entry.id === model)\n    if (info === undefined) return undefined\n    const promo = selectPromoBadge(info.promos, Date.now())\n    if (promo === undefined) return undefined\n    // The upstream's own wording, never invented copy: `label` is the region's\n    // wording and `labelEn` its English one when published.\n    const en = promo.badge.labelEn ?? promo.badge.label\n    const text = promo.badge.label === en\n      ? en\n      : { en, zh: promo.badge.label }\n    return { text, tone: promoBadgeTone(promo) }\n  }\n\n  const adapter = new EffortNormalizingAdapter({\n    profiles: () => profiles,\n    auth: INERT_AUTH,\n    // Resolve the shim's per-process shared secret as the OpenAI apiKey so\n    // pi-ai sends it as `Authorization: Bearer <shared-secret>`. The shim\n    // validates this before forwarding and resolves the real WorkBuddy token\n    // itself via the store, so the secret never reaches upstream.\n    resolveApiKey: async () => shim.token(),\n    ...resolveAttachments === undefined ? {} : { resolveAttachments },\n  }, effortCapable, resolveDefaultEffort, resolveModelBadge)\n\n  return {\n    adapter,\n    invalidate: () => {\n      profiles = buildProfiles()\n    },\n  }\n}\n"
    },
    {
      "path": "src/client/index.tsx",
      "content": "/**\n * Browser half: WorkBuddy credits and model management inside Plugin\n * configuration.\n *\n * 参考：dingminhua/dsh-connect-trae（MIT，Copyright (c) 2026 LaoDing）\n *   — 浏览器插件的注册形态（`slots` / `locale` / `settingsScope` 三项注入、\n *     `LocaleNamespaceMap` 的模块增强、`settings.plugin.item` 槽位与\n *     `key` / `priority` 的 rc.7 写法、以及整个 apply 体包 try/catch\n *     以便槽位 API 变更时降级为 console.error 而不触发\n *     \"Failed to load plugins\" 红色横幅）来自该项目，\n *     其亦注明沿用 corrinehu/dsh-workbuddy-connect 的同一模式。\n * 改动：无实质改动，仅改为本插件的命名空间与组件名。\n *\n * NOTE: the try/catch boundary of this function is mirrored (duplicated) in\n * `tests/client-fallback.spec.ts`, because the real client entry imports\n * browser-only DSH packages that cannot load in the Node test environment.\n * That test therefore does not import this function — it replicates its\n * shape. If you change the guarded body or the `console.error` message here,\n * update the mirrored `apply()` in that spec too, or the fallback test will\n * silently diverge from this real implementation.\n *\n * @module dsh-connect-workbuddy/client\n */\n\nimport { WORKBUDDY_SETTINGS_NAMESPACE_CANDIDATES, WORKBUDDY_SETTINGS_NS, WORKBUDDY_SETTINGS_SECTION_ID, WORKBUDDY_SETTINGS_SECTION_ORDER, WORKBUDDY_USAGE_PATH, withWorkBuddyRegion } from '../status-paths.ts'\nimport { createElement as h } from 'react'\nimport type { JSX } from 'react'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-settings-plugins/client'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-slots'\n// The `slots` service declaration moved host lines: `dsh-client-runtime/client`\n// owned it up to 0.1.1-rc.2, and `dsh-client-ui-renderer/client` owns it from\n// the 0.1.5 line (that package stopped being published). Both are type-only\n// side-effect imports; whichever the host ships supplies the augmentation.\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport { WorkBuddyCard } from './WorkBuddyCard.tsx'\nimport type { WorkBuddyCardInjected } from './WorkBuddyCard.tsx'\nimport { ComposerCreditsGate } from './ComposerCreditsGate.tsx'\nimport { MODEL_LABEL_PRIORITY, WORKBUDDY_PROVIDER_IDS, WorkBuddyModelLabel } from './WorkBuddyModelLabel.tsx'\nimport { declaredSlotKind, modelLabelSeats, registerModelLabelSeats } from './model-label-seat.ts'\nimport { CodebuddyLive } from './CodebuddyLive.tsx'\nimport { selectQuotaNoticeClaim, WorkBuddyQuotaNotice } from './WorkBuddyQuotaNotice.tsx'\nimport { en, zh } from './locales.ts'\nimport type { WorkBuddySettingsKey } from './locales.ts'\nimport { PluginIcon } from './plugin-icon.tsx'\nimport {\n  setSidebarPanelWanted, sidebarPanelWanted, subscribeSidebarPanelWanted,\n} from './panel-switch.ts'\nimport { openWorkBuddySettingsSection } from './settings-jump.ts'\n\n/**\n * The browser-side plugin context this entry needs.\n *\n * `ClientContext` used to be re-exported by `@deepseek-ai/dsh-client-runtime/client`;\n * that package stopped at 0.1.1-rc.2 and is neither published nor bundled on\n * the 0.1.7 line, so it cannot serve as a type source. The `slots` / `locale`\n * seats the card actually touches are declared by the client subpath modules\n * imported above, so naming them explicitly keeps this entry compilable.\n * Cordis' `Context` already carries the `effect` fiber API. (The 0.1.5-only\n * `settingsScope` service was removed with that line in 2.1.0.)\n */\nexport type WorkBuddyClientContext = Context & {\n  slots: Context['slots']\n  locale: Context['locale']\n}\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    /** WorkBuddy plugin card copy. */\n    'settings.workbuddy': WorkBuddySettingsKey\n  }\n}\n\n/** Stable browser-plugin name. */\nexport const name = 'dsh-connect-workbuddy-client'\n/**\n * Client services required by the Plugin configuration contribution.\n *\n * Deliberately only the two services that exist on BOTH host lines. The\n * settings surface differs by line — 0.1.5 provides `settingsScope`, 0.1.7\n * replaces it with `configForms` — and Cordis' dependency gate is hard: any\n * inject entry the running line does not provide keeps `apply` from ever\n * running. Probing both via `ctx.get()` (which returns undefined, never\n * throws, for an absent service) is what lets one build serve both lines.\n */\nexport const inject = ['slots', 'locale']\n\n/** Register card copy and the WorkBuddy card under Plugin configuration. */\n/**\n * Report whether the model-picker label slot landed.\n *\n * The slot is a `single` cell declared as a CHILD of `conversation.input.model`,\n * so the host calls our inject callback only once that parent entry mounts. Two\n * failures follow, and neither is visible on the page:\n *\n *   1. `register()` threw — another claim at the same priority.\n *   2. The callback never ran — the parent never mounted. Nothing throws, the\n *      disposer list is simply one shorter, and the picker shows no badges.\n *\n * Case 2 is why this exists: it produced NO trace of any kind. The state is\n * published on `window` (so a person can inspect it without reproducing the\n * symptom) and a failure is warned about exactly once per rebind. A healthy\n * load stays silent — a warning that fires when nothing is wrong stops being\n * read.\n *\n * Exported for the test. Called from `rebindSlots` (once, before the inject\n * callback exists) and again from inside the inject callback (the only place\n * that can observe a DEFERRED refusal or a late-arriving `slotKind`). Two\n * callers, one state object: the later call always supersedes the earlier, and\n * the warning is deduplicated so one failure still produces one line.\n *\n * @param state - What the registration path recorded.\n * @param target - Where to publish; defaults to the global object.\n * @returns The published view, or `undefined` when there is no global to\n *          publish onto (server rendering, a bare test).\n */\n/**\n * One word for the state of the model-label registration.\n *\n * The four outcomes need DIFFERENT fixes, and three of them look identical from\n * the picker (no badges):\n *\n *   not-reached       the client half never reached registration — a boot or\n *                     composition problem, nothing to do with the slot.\n *   parent-not-mounted  we asked, the host never called back: the parent entry\n *                     (`conversation.input.model`) is not mounted, so the child\n *                     cell does not exist yet.\n *   failed            `register()` threw (a same-priority claim).\n *   claimed           it landed; if badges are still missing the cause is\n *                     downstream (render or CSS), not here.\n *\n * @param state - What the registration path recorded.\n * @returns The verdict word.\n */\nexport function modelLabelVerdictOf(state: {\n  injectRanAt?: number | undefined\n  failure?: string | undefined\n  askedAt?: number | undefined\n  dispose?: (() => void) | undefined\n}): 'failed' | 'claimed' | 'not-reached' | 'parent-not-mounted' {\n  if (state.failure !== undefined) return 'failed'\n  if (state.injectRanAt !== undefined) return 'claimed'\n  // No ask at all: the code never got this far.\n  if (state.askedAt === undefined) return 'not-reached'\n  // It asked; the host never called back.\n  return 'parent-not-mounted'\n}\n\nexport function publishModelLabelState(\n  state: {\n    injectRanAt?: number | undefined\n    failure?: string | undefined\n    dispose?: (() => void) | undefined\n    askedAt?: number | undefined\n    rebinds?: number | undefined\n    slotKind?: string | undefined\n    seats?: number | undefined\n  },\n  target: { warn?: (message: string) => void } & Record<string, unknown> = globalThis as never,\n): Record<string, unknown> | undefined {\n  const view = {\n    verdict: modelLabelVerdictOf(state),\n    injectRanAt: state.injectRanAt,\n    askedAt: state.askedAt,\n    rebinds: state.rebinds,\n    failure: state.failure,\n    claimed: state.dispose !== undefined,\n    /**\n     * Which shape the host's declaration allowed, and how many seats were\n     * claimed for it.\n     *\n     * Without these two the picker has ONE symptom (\"no badges\") for two very\n     * different situations: a `single` host where an equal-priority rival won\n     * the cell, and a `keyed` host where a provider id was missed. `slotKind`\n     * says which contract was in force; `seats` says what this plugin did with\n     * it. `<provider count>` on a keyed host and `1` on a single host are the\n     * only healthy pairs.\n     */\n    slotKind: state.slotKind,\n    seats: state.seats,\n    at: Date.now(),\n  }\n  try {\n    target['__dshWorkBuddyModelLabel__'] = view\n  } catch {\n    // A frozen global, or no global at all: the console line below is still\n    // worth attempting, so this is not fatal.\n    return undefined\n  }\n  if (state.failure !== undefined) {\n    // ONCE PER FAILURE, not once per publish. This function now runs from two\n    // places — `rebindSlots` and the inject callback — and the callback is the\n    // one that can actually observe a deferred refusal, so both paths reach\n    // here. Warning on every call would print the same message twice for one\n    // failure, which is exactly the \"a warning that fires when nothing is new\n    // stops being read\" problem the header of this function warns about.\n    const warned = (target as { __dshWorkBuddyModelLabelWarned__?: string })\n    if (warned.__dshWorkBuddyModelLabelWarned__ !== state.failure) {\n      try {\n        target.warn?.(\n          '[dsh-connect-workbuddy] the model-picker badges could not be registered: ' + state.failure,\n        )\n        warned.__dshWorkBuddyModelLabelWarned__ = state.failure\n      } catch { /* a console that throws must not take the slots with it */ }\n    }\n  }\n  return view\n}\n\nexport function apply(ctx: WorkBuddyClientContext): void {\n  try {\n    const namespace = 'settings.workbuddy'\n    ctx.effect(() => ctx.locale.register(namespace, { zh, en }), 'dsh-connect-workbuddy: settings copy')\n    const t = ctx.locale.bind(namespace) as WorkBuddyCardInjected['t']\n\n    // Soft service probe. Property access on an undeclared service THROWS\n    // (\"cannot get property X without inject\") — `?.` guards null/undefined,\n    // not a throwing getter — while `ctx.get()` returns undefined for an\n    // absent service. Never touch `ctx.configForms` / `ctx.settingsScope`\n    // directly; go through `get`.\n    const softGet = (name: string): unknown => (ctx as unknown as { get(name: string): unknown }).get(name)\n\n    /**\n     * The credits popover's header button: open 设置 → WorkBuddy.\n     *\n     * ALWAYS A FUNCTION, never `undefined`, and it takes no route value at\n     * creation time: it reads the store seat per press and otherwise drives the\n     * shell's real chrome (see `settings-jump.ts`). That matters because the\n     * readout only renders the button when this is present, and the first\n     * `registerAllSlots()` happens before most of `apply` has finished — a\n     * route captured from `ctx.get('layout')` at that moment is `undefined` on\n     * a host whose layout plugin applies later, and the renderer caches\n     * `inject()` results by entry identity, so nothing would ever correct it.\n     *\n     * The `onGiveUp` fallback asks the plugin manager for this bundle's page,\n     * so an unrecognisable shell still lands somewhere useful.\n     */\n    const openSettingsSection = (): boolean => openWorkBuddySettingsSection({\n      label: () => t('nav.panel'),\n      // Route 1: the settings shell's store seat, which opens the dialog ON this\n      // plugin's section in one call. Probed per press (not captured here)\n      // because the sidebar bundle's apply order is not ours to assume.\n      get: softGet,\n      onGiveUp: () => {\n        // Last resort: the plugin manager's bundle page, which at least names\n        // the plugin and offers install/uninstall. Soft-probed, and its absence\n        // is simply a no-op.\n        const navigation = softGet('pluginNavigation') as { openBundle?: (name: string) => void } | undefined\n        if (navigation !== undefined && typeof navigation.openBundle === 'function') {\n          try { navigation.openBundle('dsh-connect-workbuddy') } catch { /* fallback failed: no-op */ }\n        }\n      },\n    })\n\n    let settingsScope: WorkBuddyCardInjected['settingsScope'] | undefined\n    const forms = softGet('configForms') as\n      | {\n          describe(): { getSnapshot(): { view?: { namespaces?: { ns: string }[] } } }\n          get(ns: string): WorkBuddyCardInjected['settingsScope']\n          whileServed(\n            namespaces: readonly string[],\n            register: (served: ReadonlySet<string>) => () => void,\n          ): () => void\n        }\n      | undefined\n    // 0.1.7+ only: `configForms` is the client settings surface. The legacy\n    // `settingsScope` service was removed with the 0.1.5 line (2.1.0), so\n    // there is no fallback to bind.\n\n    /**\n     * Register this plugin's page — and its nav glyph — in the Settings panel.\n     *\n     * ## Why one callback rather than two\n     *\n     * `settings.section` drives the nav row; `settings.section.icon` is rendered\n     * by the shell as `renderSlot('settings.section.icon', …, { only: row.id })`,\n     * so the glyph's cell is only meaningful while the page's id exists.\n     * Registering both from the same `inject` callback makes the pairing\n     * structural: the page's declaration is what makes the glyph addressable at\n     * all, and Cordis disposes both with this fiber.\n     *\n     * ## Why there is NO capability probe\n     *\n     * `ctx.slots.inject(name, …)` already IS the probe. It waits for the\n     * declaration and runs its callback once the slot exists; on a host that\n     * never declares `settings.section` it does nothing at all — no throw, no\n     * queued-forever registration. A probe built on anything else (a version\n     * string, an accessor the service may not expose) turns \"not supported\n     * here\" into \"never registers anywhere\", which is how a page nobody can see\n     * ships with no error at all. Let the host answer.\n     *\n     * `WorkBuddyCard` is registered with `surface: 'settings'`: the shell owns\n     * the panel chrome (title, close), so the card drops its own collapse and\n     * back affordances and keeps only its content.\n     */\n    const registerSettingsSection = (): (() => void) | undefined => {\n      try {\n        return ctx.slots.inject('settings.section' as never, () => {\n          const disposers: Array<() => void> = []\n          const injected = (): WorkBuddyCardInjected & { surface: 'settings' } =>\n            settingsScope === undefined\n              ? { t, surface: 'settings' as const }\n              : { t, settingsScope, surface: 'settings' as const }\n\n          disposers.push((ctx.slots as unknown as {\n            register(\n              options: {\n                name: string\n                id: string\n                order: number\n                label: () => string\n                locale: string\n                inject: () => WorkBuddyCardInjected & { surface: 'settings' }\n              },\n              component: unknown,\n            ): () => void\n          }).register({\n            name: 'settings.section',\n            id: WORKBUDDY_SETTINGS_SECTION_ID,\n            order: WORKBUDDY_SETTINGS_SECTION_ORDER,\n            label: () => t('nav.panel'),\n            locale: namespace,\n            inject: injected,\n          }, WorkBuddyCard))\n\n          // The glyph, addressed by the SAME id. A separate `inject` call is\n          // correct here (its own slot, its own declaration); the pairing that\n          // matters is the id, and it is the same constant in both.\n          try {\n            const iconInject = ctx.slots.inject('settings.section.icon' as never, () => {\n              const iconDisposer = (ctx.slots as unknown as {\n                register(options: { name: string; id: string; locale: string }, component: unknown): () => void\n              }).register({\n                name: 'settings.section.icon',\n                id: WORKBUDDY_SETTINGS_SECTION_ID,\n                locale: namespace,\n              }, (iconProps: { size?: number; active?: boolean } | undefined) => {\n                // The shell asks for a square edge and passes whether this row\n                // is the selected one; honouring both keeps the glyph on the\n                // same rhythm as the built-in rows' own icons.\n                const edge = typeof iconProps?.size === 'number' ? iconProps.size : 16\n                return h(PluginIcon, {\n                  size: edge,\n                  className: 'dsm-workbuddy-nav-icon',\n                  style: { borderRadius: '4px', display: 'block', opacity: iconProps?.active === false ? 0.75 : 1 },\n                })\n              })\n              disposers.push(iconDisposer)\n              return iconDisposer\n            })\n            if (typeof iconInject === 'function') disposers.push(iconInject)\n          } catch (error: unknown) {\n            // The page is the feature; the glyph is decoration. A host that\n            // declares the section but not its icon seat must still get a page.\n            console.error('[dsh-connect-workbuddy] settings nav icon failed to register (page unaffected):', error)\n          }\n\n          return () => {\n            for (const dispose of disposers) {\n              try { dispose() } catch { /* already disposed by the slot service */ }\n            }\n          }\n        })\n      } catch (error: unknown) {\n        console.error('[dsh-connect-workbuddy] settings section failed to register (host provider unaffected):', error)\n        return undefined\n      }\n    }\n\n    /**\n     * Credit readout in the composer row (`conversation.input.right`, a\n     * session-scope list slot rendered immediately before the model picker).\n     *\n     * `input.right` rather than `input.left` (ported from dsh-connect-trae's\n     * issue #71): the host renders `input.right` inside `div.trailing`'s\n     * `standardControls`, i.e. IMMEDIATELY BEFORE the model picker, while\n     * `input.left` sits at the very end of `div.tools` — 8px from the\n     * permission selector. Both are clickable, so reaching for \"完全权限\"\n     * landed on the readout and opened the credit popover. A readout is not an\n     * action; next to the model picker it stops competing with a control the\n     * user is actually aiming at. The `composer` SETTING value keeps its\n     * meaning (\"the row that carries the model picker\"), so saved profiles\n     * need no migration.\n     *\n     * 参考：dingminhua/dsh-connect-trae（MIT，Copyright (c) 2026 LaoDing）\n     *   — 该项目的 `registerComposerPoints`：无条件注册插槽、由 gate 读\n     *     `modelSelection` 投影自行决定是否渲染。本项目原先放在侧边栏底部\n     *     （`sidebar.footer.action`），那里是**单个 root 级共享行**，两个连接器\n     *     插件各占一行会互相挤压；输入框这行是 per-session 且按 provider 归属，\n     *     天然只有一个插件的积分相关。\n     *\n     * Provider-scoped on purpose: it renders only while the session's selected\n     * model belongs to this plugin, which is what keeps two connector plugins\n     * from competing for one shared row. Registration is unconditional; the\n     * gate reads the Host's `modelSelection` projection and returns null for\n     * every other provider, so nothing is drawn and no fetch loop starts while\n     * another provider is selected.\n     */\n    const registerComposerCredits = (): (() => void) | undefined => {\n      try {\n        return ctx.slots.inject('conversation.input.right' as never, () => (ctx.slots as unknown as {\n          register(\n            options: { name: string; id: string; order: number; locale: string; inject: () => WorkBuddyCardInjected },\n            component: unknown,\n          ): () => void\n        }).register({\n          name: 'conversation.input.right',\n          id: 'dsh-connect-workbuddy-composer-credits',\n          order: 4,\n          locale: namespace,\n          // `settingsScope` rides along so the gate can honor the card's\n          // per-region switch without a second writer. `onOpenSettings` is the\n          // popover's header button: it opens the plugin's own `main` panel, so\n          // the reader reaches the WIDE layout from wherever they are instead of\n          // being sent to a second, differently-shaped copy in Settings.\n          inject: () => ({\n            t,\n            position: 'composer' as const,\n            ...settingsScope === undefined ? {} : { settingsScope },\n            onOpenSettings: openSettingsSection,\n          }),\n        }, ComposerCreditsGate))\n      } catch (error: unknown) {\n        console.error('[dsh-connect-workbuddy] composer credits slot failed to register (host provider unaffected):', error)\n        return undefined\n      }\n    }\n\n    /**\n     * The load badge in the HOST's model picker.\n     *\n     * The picker renders the model name as a plain string, so a provider can\n     * only put a CHARACTER there — and a character's colour is the emoji font's\n     * business, not ours. The host therefore offers exactly one seam for this:\n     * the `conversation.input.model.label` slot, whose contract is \"render\n     * non-interactive inline content such as a coloured name or badge\" while\n     * the picker keeps owning clicks, focus and check marks. The shipped\n     * example is the official DeepSeek \"1017\" release badge, which is the same\n     * job — a coloured marker beside a model name.\n     *\n     * WHY A NEGATIVE PRIORITY (host 0.2.1-rc.2 and later). This is a `single`\n     * slot: it holds ONE cell, and `SlotCore.register()` THROWS when a second\n     * registration claims the same priority — \"single slot … already has a\n     * registration at priority 0 — register at a different priority to shadow\n     * it (lowest renders)\". The host itself now ships a contributor here\n     * (`@deepseek-ai/dsh-client-ui-deepseek-model-label-1017`, in the web-app\n     * bundle from rc.2 on) that registers at the default 0, so registering at\n     * 0 makes the two race: whichever lands second throws. Measured on\n     * 0.2.1-rc.3 that is US — the app's own crash log records, verbatim,\n     * \"single slot \\\"conversation.input.model.label\\\" already has a\n     * registration at priority 0 (registered by Kb)\" plus this entry's\n     * catch-all line \"model label slot failed to register\" twice per page\n     * load, which is the badge silently disappearing from the picker.\n     *\n     * See `MODEL_LABEL_PRIORITY` in `./WorkBuddyModelLabel.tsx` for the full\n     * ordering, the measured evidence, and the deliberate absence of any\n     * inter-plugin coordination (project invariant, `docs/DESIGN.md` §零).\n     *\n     * HOW MANY SEATS, AND WHY THAT IS READ AT MOUNT. `single` holds one cell, so\n     * exactly one registration is legal there. A `keyed` host gives each\n     * `options.key` its own cell, and one cell per provider id is what this\n     * plugin actually wants: it then draws its OWN rows and nothing else, qoder\n     * and trae stop sharing a cell with it, and a provider with no contribution\n     * falls through to the host's own fallback. Which of the two shapes is\n     * legal is the HOST's declaration, not this plugin's choice, so the kind is\n     * read from `ctx.slots.spec(...)` at mount and the seat list is derived from\n     * it (`./model-label-seat.ts`). One build therefore serves both lines — and\n     * a host that cannot be inspected gets the single seat, which is what every\n     * released version of this plugin already does.\n     *\n     * THE COST IS PAID ON ANOTHER PLUGIN'S ROWS, and it is worth stating where\n     * the registration happens: holding this cell means the host's own\n     * `dsh-client-ui-deepseek-model-label-1017` badge is NOT rendered on the\n     * DeepSeek rows it was written for. That is not a defect and not something\n     * to fix by inspecting the slot ledger — it is the price of §零, recorded in\n     * `docs/DESIGN.md` and argued in the 5.8.2 CHANGELOG. Issue #138 is a user\n     * meeting that price for the first time; the disposition is to state it\n     * plainly rather than to coordinate at runtime. On a `keyed` host that price\n     * is not paid at all: each provider keeps its own cell, so 1017's badge\n     * returns to the DeepSeek rows without anyone negotiating.\n     */\n    /**\n     * WHY THIS RECORDS AN OUTCOME, not just a disposer.\n     *\n     * Claiming the cell can fail in two DIFFERENT ways and both are silent:\n     *\n     *  1. `register()` throws — a `single` slot with another claim at the same\n     *     priority. The catch logs, the page looks fine, the badges are gone.\n     *  2. `inject()` never runs — the slot is declared as a child of\n     *     `conversation.input.model`, so the host only calls back once THAT\n     *     entry mounts. If it never mounts (a session-less surface, an older\n     *     host, a renamed parent), nothing throws at all: the callback simply\n     *     does not happen and the disposer list stays one shorter.\n     *\n     * Case 2 left no trace of any kind, which is why this plugin could look\n     * healthy while the picker showed no badges. Recording the timestamp of the\n     * callback and the reason for a failure turns \"did it land?\" from a guess\n     * into a fact the diagnostics row can print.\n     */\n    const modelLabelState: {\n      /** Set inside the inject callback: the host called us for this slot. */\n      injectRanAt?: number\n      /** Set when `register()` threw. */\n      failure?: string\n      /** The disposer, when the host eventually asked for the cell. */\n      dispose?: (() => void) | undefined\n      /**\n       * Set the moment `registerModelLabel()` is CALLED, before the host has a\n       * chance to answer.\n       *\n       * This exists so the published view can tell three states apart instead of\n       * two. Without it, \"the plugin never got this far\" and \"the plugin asked\n       * and the host never answered\" both publish `undefined`, and those need\n       * completely different fixes.\n       */\n      askedAt?: number\n      /** How many times `rebindSlots` has run — proves the client half booted. */\n      rebinds?: number\n      /**\n       * The kind the running host declared for the label slot, as read at mount.\n       *\n       * `undefined` means the host did not answer the inspection (an older line\n       * without `spec()`, or a throw) — NOT that the slot is missing. The\n       * published view needs it because \"we registered one seat on a keyed host\"\n       * and \"we registered two seats on a single host\" are different bugs that\n       * look identical from the picker.\n       */\n      slotKind?: string\n      /** How many registrations this plugin made for the slot. */\n      seats?: number\n    } = {}\n    /** The verdict for the console line (see `modelLabelVerdictOf`). */\n    const modelLabelVerdict = (): string => modelLabelVerdictOf(modelLabelState)\n    const registerModelLabel = (): (() => void) | undefined => {\n      modelLabelState.askedAt = Date.now()\n      /**\n       * The refusal path, shared by the eager and the deferred call.\n       *\n       * REPUBLISHES, and that is not cosmetic. `rebindSlots` publishes once, and\n       * on the normal boot it publishes BEFORE this callback exists: `inject()`\n       * defers the callback until `conversation.input.model` mounts, so the\n       * published view is a snapshot of a registration that has not happened\n       * yet. Without this line the failure lands in a state object that nothing\n       * reads again, and `window.__dshWorkBuddyModelLabel__` keeps\n       * `failure: undefined` with verdict `parent-not-mounted` — the exact\n       * opposite of the truth, in the surface built to state it.\n       */\n      const refuse = (error: unknown): undefined => {\n        const message = error instanceof Error ? error.message : String(error)\n        modelLabelState.failure = message\n        console.error('[dsh-connect-workbuddy] model label slot failed to register (host provider unaffected):', error)\n        publishModelLabelState(modelLabelState)\n        return undefined\n      }\n      try {\n        return ctx.slots.inject('conversation.input.model.label' as never, () => {\n          // THIS LINE IS THE EVIDENCE. The host calls back only after\n          // `conversation.input.model` has mounted and declared the child cell;\n          // if the row never appears, the callback never runs and NOTHING throws\n          // (see the note above `modelLabelState`).\n          modelLabelState.injectRanAt = Date.now()\n          // The KIND is the host's declaration, read from the live registry — a\n          // plugin's `SlotMap` augmentation describes what this build hopes for,\n          // not what the running host declared. See `modelLabelSeats`.\n          const kind = declaredSlotKind(ctx.slots, 'conversation.input.model.label')\n          const seats = modelLabelSeats({\n            name: 'conversation.input.model.label',\n            kind,\n            providerIds: WORKBUDDY_PROVIDER_IDS,\n            priority: MODEL_LABEL_PRIORITY,\n          })\n          const registry = ctx.slots as unknown as {\n            register(\n              options: { name: string, priority: number, key?: string },\n              component: unknown,\n            ): () => void\n          }\n          // ATOMIC: 2–3 seats, any one of which can be refused. A plain `.map()`\n          // would strand the seats that already landed (their disposers would\n          // die with the thrown array), leaving live cells nothing can release —\n          // see `registerModelLabelSeats`.\n          //\n          // THE CATCH IS INSIDE THE CALLBACK, on purpose. `inject()` does not\n          // necessarily run its callback now: when the slot is not declared yet\n          // it subscribes and runs it LATER, and a later throw is re-thrown by\n          // the renderer's own `changed()` handler out of a `queueMicrotask`,\n          // where no call-site try/catch can reach it — the user gets a renderer\n          // error banner on the first paint after a restart. Keeping the catch\n          // here turns every refusal into the log line and the diagnostics state\n          // that exist to explain it. (Trae paid for this lesson in issue #74;\n          // the seat list is 2 entries now, so a refusal is twice as reachable.)\n          try {\n            const dispose = registerModelLabelSeats(seats, seat => registry.register(seat, WorkBuddyModelLabel))\n            modelLabelState.slotKind = kind ?? 'unknown'\n            modelLabelState.seats = seats.length\n            // Republish for the same reason `refuse` does: the one publish in\n            // `rebindSlots` runs before a deferred callback ever executes, so\n            // without this the two fields above would never reach `window`.\n            publishModelLabelState(modelLabelState)\n            return dispose\n          } catch (error: unknown) {\n            refuse(error)\n            // The callback's contract is a disposer, never `undefined`.\n            return () => {}\n          }\n        })\n      } catch (error: unknown) {\n        // Only reachable when `inject()` itself throws, i.e. the slot is not\n        // declared at all on this host.\n        return refuse(error)\n      }\n    }\n\n    /**\n     * The sidebar glyph for the WorkBuddy panel row.\n     *\n     * The sidebar renders `sidebar.panellist` registrants with `{ size, active }`\n     * inside a `currentColor`-themed glyph cell, so the brand mark is drawn as a\n     * small `<img>` — the PNG's own colours read as the plugin's identity, and\n     * the row's selection state is the host's to paint around it.\n     */\n    function WorkBuddyPanelIcon(props: { size?: number }): JSX.Element {\n      const edge = typeof props.size === 'number' && props.size > 0 ? props.size : 16\n      return h(PluginIcon, { className: 'dsm-workbuddy-panel-icon', size: edge })\n    }\n\n    /**\n     * The WorkBuddy panel in the sidebar (`sidebar.panellist` row + `main` keyed\n     * page), mirroring how the host's own Plugins row and dsh-skill-mcp-panel\n     * put a full page in the centre column.\n     *\n     * OPT-IN (`Config.sidebarPanel`, default false). Registering it is NOT the\n     * same as showing it: `ui-sidebar` builds the nav row from the slot's ENTRY\n     * METADATA (`usePanels` → `PanelRow` with `options.label` and\n     * `renderSlot(...)` as the glyph), so a component returning `null` leaves a\n     * blank but still-clickable button rather than no button. The row therefore\n     * has to be registered only while the switch is on, which is what\n     * {@link syncPanelRegistration} owns. See `panel-switch.ts` for the store\n     * that decision rides on.\n     *\n     * Back navigation reuses the host's layout service: `selectPanel(null)`\n     * hands the main area back to the conversation. It is soft-probed, so a\n     * host that never declares `layout` simply renders the page without the back\n     * affordance instead of blocking the whole plugin (the same degradation the\n     * card already promises for a missing settings form).\n     */\n    /**\n     * The `main` key this plugin's full page is registered under.\n     *\n     * Also the id the composer readout asks `layout.selectPanel` for, so the two\n     * cannot drift: a rename here that missed `openFullPage` below would leave a\n     * button that throws \"main panel is not registered\".\n     */\n    const PANEL_ID = 'dsh-connect-workbuddy'\n\n    /** Hand the centre column back to the conversation. */\n    const backToConversation = (): void => {\n      const layout = softGet('layout') as { selectPanel?: (id: string | null) => void } | undefined\n      if (layout !== undefined && typeof layout.selectPanel === 'function') layout.selectPanel(null)\n    }\n\n    /**\n     * Open the FULL page from anywhere in the plugin (the composer readout's\n     * button, and anything else that wants to send the reader there).\n     *\n     * The page is a `main` panel, so `layout.selectPanel` is the supported route\n     * and needs no private key of another bundle — unlike the old\n     * `openBundle('/plugins/…')` approach, which asked the Plugins page to\n     * select a bundle and only worked while that page's own service existed.\n     *\n     * IT THROWS WHEN THE KEY IS UNREGISTERED, by the host's own rule\n     * (`layout.selectPanel: main panel \"…\" is not registered`). That is why the\n     * `main` registration below is UNCONDITIONAL while the sidebar ROW is\n     * optional: the row claims a global nav seat and is off by default, but the\n     * page behind it has to exist for this function to be callable at all. The\n     * catch is here rather than in the caller so a stripped profile degrades to\n     * \"the button does nothing\" instead of an error inside a click handler.\n     *\n     * @returns whether the page was opened.\n     */\n    const openFullPage = (): boolean => {\n      const layout = softGet('layout') as { selectPanel?: (id: string | null) => void } | undefined\n      if (layout === undefined || typeof layout.selectPanel !== 'function') return false\n      try {\n        layout.selectPanel(PANEL_ID)\n        return true\n      } catch {\n        return false\n      }\n    }\n\n    /**\n     * The full page: a `main` panel keyed by {@link PANEL_ID}.\n     *\n     * Registered ALWAYS, independently of the sidebar row. They used to share one\n     * lifetime, which made the page reachable only while the optional nav row was\n     * switched on — and the nav row is a global seat, off by default, that most\n     * users never turn on. The page is what the composer readout's button opens,\n     * so tying the two together meant that button could not exist.\n     */\n    const registerMainPage = (): (() => void) | undefined => {\n      try {\n        return ctx.slots.inject('main' as never, () => (ctx.slots as unknown as {\n          register(options: { name: string; key: string; locale: string; inject: () => WorkBuddyCardInjected & { surface: 'page'; backToConversation: () => void } }, component: unknown): () => void\n        }).register({\n          name: 'main',\n          key: PANEL_ID,\n          locale: namespace,\n          inject: () => settingsScope === undefined\n            ? { t, surface: 'page' as const, backToConversation }\n            : { t, settingsScope, surface: 'page' as const, backToConversation },\n        }, WorkBuddyCard))\n      } catch (error: unknown) {\n        console.error('[dsh-connect-workbuddy] full page failed to register (host provider unaffected):', error)\n        return undefined\n      }\n    }\n\n    /**\n     * The OPTIONAL sidebar nav row that points at {@link registerMainPage}'s page.\n     *\n     * Separate from the page for the reason above: `sidebar.panellist` builds its\n     * rows from ENTRY METADATA (`usePanels`), so this is the only half that has to\n     * come and go with the switch. Registering the row is what makes the page\n     * reachable from the sidebar; the page itself exists either way.\n     */\n    const registerPanelRow = (): Array<() => void> => {\n      const disposers: Array<() => void> = []\n      try {\n        disposers.push(ctx.slots.inject('sidebar.panellist' as never, () => (ctx.slots as unknown as {\n          register(options: { name: string; id: string; order: number; label: () => string; locale: string }, component: unknown): () => void\n        }).register({\n          name: 'sidebar.panellist',\n          id: PANEL_ID,\n          order: 2,\n          label: () => t('nav.panel'),\n          locale: namespace,\n        }, WorkBuddyPanelIcon)))\n      } catch (error: unknown) {\n        console.error('[dsh-connect-workbuddy] sidebar panel row failed to register (host provider unaffected):', error)\n      }\n      return disposers\n    }\n\n    /**\n     * The live panel registrations, kept SEPARATE from {@link liveDisposers}.\n     *\n     * They are the only slots in this plugin that come and go while the page is\n     * open (the opt-in switch), so owning them apart from the rest means\n     * flipping the switch does not dispose and re-create the card, the composer\n     * readout and the five other seats — which would be a visible flicker on the\n     * Plugins page for a change that has nothing to do with it.\n     */\n    let panelDisposers: Array<() => void> = []\n\n    /**\n     * Bring the panel registrations in line with the opt-in switch.\n     *\n     * Dispose FIRST, then register, for the reason spelled out on\n     * {@link rebindSlots}: a live `key` / `id` cannot be registered twice, and\n     * the throw would be swallowed into \"no entry at all\".\n     *\n     * Re-registering (rather than only unregistering) is what keeps the entry\n     * fresh after a settings-scope rebind: the renderer caches each entry's\n     * `inject` result by object identity, so an entry created before the scope\n     * landed would keep serving props without it forever.\n     */\n    const syncPanelRegistration = (): void => {\n      for (const dispose of panelDisposers) {\n        try { dispose() } catch { /* already disposed by the slot service */ }\n      }\n      panelDisposers = []\n      if (!sidebarPanelWanted()) return\n      panelDisposers = registerPanelRow()\n    }\n\n    /**\n     * The SAME readout in the ambient dock below the composer card (issue #62).\n     *\n     * Registered unconditionally, like the composer seat, because the CHOICE\n     * between the two seats lives in the gate: it renders in the seat the\n     * setting names and returns null in the other. Registering only the chosen\n     * seat would mean re-registering on every settings change, and the seat is\n     * exactly the kind of thing a user flips once while looking at the result.\n     *\n     * WHY THIS SEAT EXISTS: the composer tool row is a list seat shared with any\n     * other plugin that registers there, and issue #62 is one report of the\n     * readout disappearing when another plugin was installed. This row is where\n     * the shell renders its own round/step/token pills, so it is a place a user\n     * already reads session numbers from.\n     *\n     * `order` places it after the shell's own pills (`stats` registers at 0), so\n     * the shipped statistics stay leftmost and the readout reads as an addition\n     * rather than a replacement.\n     */\n    const registerStatsCredits = (): (() => void) | undefined => {\n      try {\n        return ctx.slots.inject('conversation.composer.dock' as never, () => (ctx.slots as unknown as {\n          register(\n            options: { name: string; id: string; order: number; locale: string; inject: () => WorkBuddyCardInjected },\n            component: unknown,\n          ): () => void\n        }).register({\n          name: 'conversation.composer.dock',\n          id: 'dsh-connect-workbuddy-stats-credits',\n          order: 10,\n          locale: namespace,\n          // The SAME injection as the composer seat, minus the position: both\n          // seats render the same component, so a prop wired into one and not\n          // the other makes a control appear or vanish depending on a setting\n          // that has nothing to do with it.\n          inject: () => ({\n            t,\n            position: 'stats' as const,\n            ...settingsScope === undefined ? {} : { settingsScope },\n            onOpenSettings: openSettingsSection,\n          }),\n        }, ComposerCreditsGate))\n      } catch (error: unknown) {\n        console.error('[dsh-connect-workbuddy] stats credits slot failed to register (host provider unaffected):', error)\n        return undefined\n      }\n    }\n\n    /**\n     * The live CodeBuddy turn pill, in the same ambient dock as the readout.\n     *\n     * `order` 11 puts it immediately after the credit readout (10) and still\n     * right of the shell's own pills (0): the two numbers a user glances at while\n     * a turn runs sit together. The component renders `null` whenever no turn is\n     * live, which is the normal case — the bridge is off by default — so an\n     * unused seat costs one poll interval and nothing on screen.\n     *\n     * THE SESSION ID IS THE PILL'S DISPLAY CONDITION. `conversation.composer.dock`\n     * is declared `scope: 'session'`, so the registration's `inject` receives the\n     * session id and the pill can keep only the rows that session started. The\n     * board itself is host-wide (one route for every session in the process), so\n     * without this the pill would describe whatever turn is newest anywhere —\n     * including one from another tab, about a directory the reader is not in.\n     * Unlike the credit readout there is deliberately no provider gate: the CLI\n     * route is model-independent, and a turn started from a DeepSeek session is\n     * exactly a case the readout has to cover.\n     */\n    const registerCliLive = (): (() => void) | undefined => {\n      try {\n        return ctx.slots.inject('conversation.composer.dock' as never, () => (ctx.slots as unknown as {\n          register(\n            options: { name: string; id: string; order: number; locale: string; inject: (sessionId: string) => { t: (key: WorkBuddySettingsKey, params?: Record<string, unknown>) => string; sessionId: string } },\n            component: unknown,\n          ): () => void\n        }).register({\n          name: 'conversation.composer.dock',\n          id: 'dsh-connect-workbuddy-cli-live',\n          order: 11,\n          locale: namespace,\n          inject: (sessionId: string) => ({ t, sessionId }),\n        }, CodebuddyLive))\n      } catch (error: unknown) {\n        console.error('[dsh-connect-workbuddy] cli live slot failed to register (host provider unaffected):', error)\n        return undefined\n      }\n    }\n\n    /**\n     * The frame-wide quota notice, DECLINED so the host keeps its own Toast\n     * (issue #63 follow-up, the maintainer's call on a screenshot).\n     *\n     * WHAT WAS WRONG. The previous build claimed `QUOTA` and rendered the\n     * supplement as an inline `<span>` in this seat. The chain's own contract\n     * says a claiming entry \"takes over the surface\" — so claiming REPLACED the\n     * host's generic warning Toast, and the replacement was not a Toast: an\n     * inline span has no `position: fixed`, no centring, no background and no\n     * fade, so it parked at the TOP-LEFT of `shell.overlay` (an `inset: 0`\n     * layer) and stayed there until the next notice. The maintainer read it, on\n     * screen, as a box that had not been there before — and it had not.\n     *\n     * WHY DECLINING IS THE FIX, not a worse one. The host's own sentence is\n     * already correct and already appears in the turn's failure row inside the\n     * conversation (`message.failure.quota`, via `failureMessage` in\n     * `ui-chat`'s MessageItem) — the place the user is actually reading when a\n     * turn fails. Taking over the frame-wide surface bought this plugin nothing\n     * except a second, uglier copy of a sentence the host already draws where it\n     * matters. Declining the claim returns the seat to the host: the Toast is\n     * the host's own design, and this plugin stops imposing a look on a surface\n     * it does not own.\n     *\n     * The supplement itself is NOT lost — it rides in the conversation, which is\n     * the only surface that is actually in the user's eyeline (see\n     * `registerStatsCredits` and the failure row). The `select` below is\n     * therefore an explicit, documented DECLINE of every code rather than a\n     * deletion of the registration: the seat stays claimed in one place with its\n     * rationale attached, so a future reader does not re-add the takeover\n     * without re-reading why it was removed.\n     */\n    const registerQuotaNotice = (): (() => void) | undefined => {\n      try {\n        return ctx.slots.inject('shell.quota-notice' as never, () => (ctx.slots as unknown as {\n          register(\n            options: {\n              name: string\n              locale: string\n              select: (owner: unknown) => unknown\n              inject: () => { t: WorkBuddyCardInjected['t'] }\n            },\n            component: unknown,\n          ): () => void\n        }).register({\n          name: 'shell.quota-notice',\n          locale: namespace,\n          // Declining every owner leaves the chain's all-decline case in charge,\n          // which is the host's own generic warning Toast. The rule lives in\n          // `selectQuotaNoticeClaim` so it has exactly one home and its own test;\n          // `claimsQuotaNotice` still exports the retired claim set as history.\n          select: selectQuotaNoticeClaim,\n          inject: () => ({ t }),\n        }, WorkBuddyQuotaNotice))\n      } catch (error: unknown) {\n        console.error('[dsh-connect-workbuddy] quota notice slot failed to register (host provider unaffected):', error)\n        return undefined\n      }\n    }\n\n    /**\n     * Every slot this plugin contributes, and how to (re)create them.\n     *\n     * Kept as one list because the binding of `settingsScope` and the slot\n     * registrations must move TOGETHER: see {@link bindSettingsScope} for why a\n     * late-arriving namespace has to produce fresh registrations rather than a\n     * mutated closure.\n     *\n     * The configuration page is `settings.section` — ONE registration under an\n     * id this plugin owns, so there is no inventory name to match and no\n     * spelling to get wrong (see {@link WORKBUDDY_SETTINGS_SECTION_ID}). The\n     * former `plugins.bundle.config` / `plugins.row.config` pair is GONE with\n     * 5.19.0: the same configuration must not have two editing entries.\n     */\n    const registerAllSlots = (): Array<() => void> => [\n      registerSettingsSection(),\n      registerComposerCredits(),\n      registerStatsCredits(),\n      registerCliLive(),\n      registerQuotaNotice(),\n      // Recorded, not just appended: `modelLabelState` is the only place that\n      // knows whether the host ever asked for the cell (see the publish block in\n      // `rebindSlots`).\n      (() => {\n        const dispose = registerModelLabel()\n        modelLabelState.dispose = dispose\n        return dispose\n      })(),\n      // The full PAGE is always-on: the composer readout's button opens it, and a\n      // `main` panel has to exist for `layout.selectPanel` to accept the key.\n      registerMainPage(),\n      // The sidebar NAV ROW alone is conditional, so it is owned by\n      // {@link syncPanelRegistration} rather than this list. It registers the row\n      // that points at the page above; the page does not depend on it.\n    ].filter((disposer): disposer is () => void => disposer !== undefined)\n\n    /**\n     * Disposers of the slots registered for the CURRENT binding.\n     *\n     * Declared before {@link bindSettingsScope} because that function closes\n     * over it and reassigns it; the binding is only armed at the end of `apply`,\n     * so this is initialised by then either way — hoisting it keeps that\n     * ordering a non-requirement rather than a trap.\n     */\n    let liveDisposers: Array<() => void> = []\n\n    /**\n     * Replace the live registrations with a fresh set.\n     *\n     * ORDER MATTERS: dispose FIRST, then register.\n     *\n     * The ledger is a KEYED slot with one entry per `key` per priority, so\n     * registering a key that is still live THROWS (`already has an entry for\n     * key …`). Every registration in this entry is isolated by its own\n     * try/catch, so the failure is not visible — the throw is logged and the\n     * key is simply left with NO entry, because the old one was just disposed\n     * by the `previous` loop. Registering before disposing therefore produces\n     * an EMPTY ledger, which is a worse version of the very defect this\n     * function exists to prevent.\n     */\n    const rebindSlots = (): void => {\n      for (const dispose of liveDisposers) {\n        try { dispose() } catch { /* already disposed by the slot service */ }\n      }\n      liveDisposers = []\n      modelLabelState.rebinds = (modelLabelState.rebinds ?? 0) + 1\n      liveDisposers = registerAllSlots()\n      // Say what actually landed, once per rebind.\n      //\n      // The issue #55 reporter's own point: the whole `apply` body is wrapped in\n      // a try/catch that only logs, so \"no card\" and \"worked fine\" look\n      // IDENTICAL on the page — locating that took them far longer than the fix\n      // did. A single line naming the count and where the settings form came\n      // from turns the next occurrence into a one-look diagnosis:\n      //\n      //   [dsh-connect-workbuddy] registered 6 slots (settings form: bound, sidebar panel: off)\n      //   [dsh-connect-workbuddy] registered 6 slots (settings form: none — page is read-only, ...)\n      //\n      // Deliberately `console.info`, not `warn`/`error`: this is the healthy\n      // path, and a warning-per-page-load would train users to ignore the one\n      // channel that matters when something really is wrong.\n      // EXPOSE THE SLOT STATE ON `window`, and shout when the model label did\n      // not land.\n      //\n      // Why this exists: a `single` slot whose parent entry never mounts (or\n      // whose claim collides) fails SILENTLY — the picker simply has no badges,\n      // the page looks healthy, and there is nothing for the user to report\n      // except \"it is not there\". That is exactly the position a user was in\n      // when this was added. The two facts that identify the cause — did the\n      // inject callback ever run, and did `register()` throw — are known only\n      // here, so they are published rather than guessed at.\n      //\n      // `warn`, not `info`, and only on the broken path: a healthy load stays\n      // quiet, which is the only way a warning keeps meaning anything.\n      publishModelLabelState(modelLabelState)\n      try {\n        console.info(\n          `[dsh-connect-workbuddy] registered ${String(liveDisposers.length)} slots `\n          + `(settings form: ${settingsScope === undefined ? 'none — page is read-only' : 'bound'}, `\n          + `sidebar panel: ${sidebarPanelWanted() ? 'on' : 'off'}, `\n          + `model label: ${modelLabelVerdict()}`\n          + `${modelLabelState.failure === undefined ? '' : ` (${modelLabelState.failure})`})`,\n        )\n      } catch { /* a host without console must still get its slots */ }\n      // The panel rides its OWN switch, so it is reconciled rather than listed:\n      // an already-on panel is torn down and re-registered here so its `inject`\n      // closure sees the scope that was just bound.\n      syncPanelRegistration()\n    }\n\n    /**\n     * Bind `settingsScope` to whichever namespace the Host really serves, and\n     * RE-REGISTER every slot when that answer changes.\n     *\n     * Why this is not a one-shot read at startup — the shipped 4.3.0 defect\n     * (issue #46): the mirror is filled by an async `remote.settings.describe()`,\n     * so at `apply` time `view` is usually still absent. The old code read that\n     * absence as \"the declared name must be right\", bound\n     * `forms.get('workbuddy')`, and never looked again. `ConfigFormController.\n     * derive()` matches the namespace EXACTLY, so the guessed form stayed\n     * `unavailable` forever; the composer gate — reading only that scope —\n     * judged the opt-out switch `undefined !== false` and kept rendering the\n     * readout. Unticking the box wrote `false` correctly and changed nothing on\n     * screen.\n     *\n     * `whileServed` is the Host's own idiom for this (`mirror.subscribe` plus an\n     * immediate sync). It is strictly better than re-reading the snapshot by\n     * hand because it ALSO withdraws the binding if the Host stops serving our\n     * namespace, and it hands `register` the set of namespaces actually served\n     * — so the choice is made from live data instead of a captured guess.\n     *\n     * `register` runs on the unserved→served EDGE, not on every mirror update\n     * (see the service's `sync`), so the disposal below is not a churn loop: it\n     * clears whatever a previous edge left registered. That replacement is NOT\n     * optional, because the renderer caches each entry's inject result by object\n     * identity (`rootInjectCache` / `cachedRootInject` in\n     * `dsh-client-ui-renderer`: `if (!props) { props = runInject(...) }`), so an\n     * entry registered before the mirror landed is never re-evaluated. Late\n     * binding can therefore only work if the OLD registrations are disposed and\n     * NEW ones created — which is what this callback does.\n     */\n    const bindSettingsScope = (): void => {\n      if (forms === undefined || typeof forms.whileServed !== 'function') {\n        // No settings surface on this host (or a pre-`whileServed` line): fall\n        // back to binding the declared name once and registering once. The card\n        // then renders read-only, which is the documented degradation.\n        settingsScope = forms?.get(WORKBUDDY_SETTINGS_NS)\n        liveDisposers = registerAllSlots()\n        syncPanelRegistration()\n        return\n      }\n      // Wrapped in `ctx.effect` so the watch is torn down with the plugin fiber,\n      // per the service's contract (`whileServed` registers nothing on our\n      // context by itself).\n      ctx.effect(() => forms.whileServed(\n        WORKBUDDY_SETTINGS_NAMESPACE_CANDIDATES,\n        (served) => {\n          // The mirror has spoken. The candidate list is ORDERED, so the first\n          // spelling the Host actually serves wins; the `/workbuddy/i` sweep is\n          // a last resort for an entry id naming this plugin in a way the\n          // candidate list does not anticipate (a wrapper prefix, a suffix).\n          const ns = WORKBUDDY_SETTINGS_NAMESPACE_CANDIDATES.find(candidate => served.has(candidate))\n            ?? [...served].find(entry => /workbuddy/i.test(entry))\n          settingsScope = ns === undefined ? undefined : forms.get(ns)\n          // Replace, never append: the renderer's inject cache is keyed by entry\n          // identity, so a stale registration would keep serving stale props.\n          rebindSlots()\n          return () => {\n            for (const dispose of liveDisposers) {\n              try { dispose() } catch { /* already disposed by the slot service */ }\n            }\n            liveDisposers = []\n            for (const dispose of panelDisposers) {\n              try { dispose() } catch { /* already disposed by the slot service */ }\n            }\n            panelDisposers = []\n          }\n        },\n      ), 'dsh-connect-workbuddy: settings namespace binding')\n      // AND REGISTER ANYWAY, without waiting for the edge.\n      //\n      // `whileServed` fires `register` only on the unserved→served EDGE. When\n      // the mirror's FIRST answer already contains our namespace, the service's\n      // `sync()` runs inside `whileServed` itself and the edge fires there — so\n      // this call is the same path, and the disposers it creates are the ones\n      // the watch later replaces. But when the FIRST answer does NOT contain it\n      // (a name the candidate list does not anticipate, a settings surface that\n      // answers late or fails, a deployment that mounts the plugin without a\n      // configurable entry at all), no edge ever fires and the card would never\n      // be registered — issue #55: an empty Plugins page with no error, because\n      // the whole `apply` body is wrapped in a try/catch that only logs.\n      //\n      // The card is useful WITHOUT the form: it reads its state from the Host's\n      // own status route and renders read-only, exactly as the `forms ===\n      // undefined` branch above already does. So registration must not be\n      // conditional on the settings namespace, and a later edge — if one ever\n      // comes — replaces these registrations with bound ones.\n      //\n      // `liveDisposers` is REPLACED, not appended to: when the edge fired\n      // synchronously inside `whileServed`, this would otherwise dispose nothing\n      // and register a second copy of every key at the same priority, which the\n      // slot service refuses outright (\"already has an entry for key …\"). Every\n      // previous registration is torn down first, so exactly one set is live.\n      rebindSlots()\n    }\n\n    bindSettingsScope()\n\n    /**\n     * Follow the opt-in switch, and SEED it from the Host.\n     *\n     * The seed is a status read rather than the settings scope on purpose. This\n     * namespace's browser mirror is documented as stale on the affected 0.1.7\n     * deployments, and here a stale `false` would mean the row never appears —\n     * with no later event to correct it, because `whileServed` only fires on a\n     * namespace edge, not on a value change. The Host's own answer is the\n     * authority (`sidebarPanelEnabled` on the usage document), exactly as it is\n     * for the other Host-carried switches.\n     *\n     * A failed read is NOT an error to show: OFF is a legitimate and, in fact,\n     * the default answer, so a plugin whose status route is unreachable simply\n     * gets no row. There is nothing the user could do about it from here.\n     *\n     * The SUBSCRIPTION is what makes the switch live: the card calls\n     * `setSidebarPanelWanted` after a verified write, so the row appears and\n     * disappears without a reload. `ui-layout` drops an `activePanelId` whose\n     * `main` key has gone, so switching off while the page is open returns the\n     * centre column to the conversation on its own.\n     */\n    ctx.effect(\n      () => subscribeSidebarPanelWanted(syncPanelRegistration),\n      'dsh-connect-workbuddy: sidebar panel opt-in',\n    )\n    void (async () => {\n      try {\n        const response = await fetch(withWorkBuddyRegion(WORKBUDDY_USAGE_PATH, 'cn'), {\n          headers: { accept: 'application/json' },\n        })\n        if (!response.ok) return\n        const document = await response.json() as { sidebarPanelEnabled?: unknown }\n        if (document.sidebarPanelEnabled === true) setSidebarPanelWanted(true)\n      } catch { /* no answer means no row; the switch stays off */ }\n    })()\n  } catch (error: unknown) {\n    // Degrade silently on the page: the host provider still serves models.\n    // Developers see the full cause in the browser console; users see no banner.\n    console.error('[dsh-connect-workbuddy] client card failed to load (host provider unaffected):', error)\n  }\n}\n"
    },
    {
      "path": "src/image-tool.ts",
      "content": "/**\n * `workbuddy_draw_image`：把 WorkBuddy 的文生图能力（国内区与国际区各自的\n * `text-to-image` 模型）暴露成一个 DSH agent 工具。\n *\n * 为什么手写 ToolDefinition 而不 import `@deepseek-ai/dsh-tools` 的 `defineTool`：\n * 宿主 `Tools.register` 只校验两件事——`output.render` 是函数、`output.schema` 是\n * 受支持的 JSON Schema；`schemaOf()` 把 `parameters` **原样**投影给模型。也就是说\n * raw JSON Schema 完全够用，而 `defineTool` 额外提供的只有「按 spec 编译 schema +\n * 代校验参数」这一层包装。手写换来的是：零新 peer 依赖、不需要动态 import 兜底、\n * 不会碰到 tests/host-peers.spec.ts 对 `lib/bin.js` 可达图的断言（那里禁止除\n * `node:` 外的任何裸说明符）。\n *\n * 代价是参数校验要自己做——见 {@link createImageTool} 的 execute。\n *\n * @module dsh-connect-workbuddy/image-tool\n */\n\nimport { mkdir, readFile, writeFile } from 'node:fs/promises'\nimport { tmpdir } from 'node:os'\nimport { join } from 'node:path'\nimport { fileURLToPath, pathToFileURL } from 'node:url'\nimport type { WorkBuddyCredential } from './auth.ts'\nimport { pruneTempDir, TEMP_MEDIA_KEEP } from './temp-files.ts'\nimport { regionOf } from './upstream.ts'\nimport {\n  IMAGE_SIZE_LIMITS_WIDE,\n  IMAGE_TAG_IMAGE_TO_IMAGE,\n  IMAGE_TAG_TEXT_TO_IMAGE,\n  MAX_INPUT_IMAGE_BYTES,\n  WorkBuddyImageError,\n  imageDataUrl,\n  imageMimeForPath,\n  imageModelChoices,\n  imageSizeLimitsOf,\n  isBareBase64Image,\n  isWatermarkFreeImageModel,\n  parseImageDataUrl,\n  pickMediaModel,\n  sniffImageMime,\n  type WorkBuddyImageOutcome,\n  type WorkBuddyImageSizeLimits,\n  type WorkBuddyMediaModel,\n} from './image-gen.ts'\n\n/** 工具名。宿主禁止 `run_code`，这个名字与其它 connect 插件的命名习惯一致。 */\nexport const WORKBUDDY_IMAGE_TOOL_NAME = 'workbuddy_draw_image'\n\n/** 工具单次执行的上限。实测一张图 17–39 秒，留足余量。 */\nconst IMAGE_TOOL_TIMEOUT_MS = 180_000\n/** 媒体模型目录的缓存时长：目录变化很慢，不必每张图都重新读一遍。 */\nexport const MEDIA_MODEL_TTL_MS = 5 * 60_000\n/** 下载远程输入图的上限（只覆盖 http(s) 那一次 GET，不含生图本身）。 */\nconst IMAGE_INPUT_TIMEOUT_MS = 30_000\n/** 失败后的冷却：生图按张扣积分，连续重试会在几秒内烧掉几十积分。 */\nconst FAILURE_COOLDOWN_MS = 30_000\n\n/** 宿主 ContentBlock 的最小结构（只需要文本块）。 */\nexport interface ImageToolContentBlock {\n  readonly type: 'text'\n  readonly text: string\n}\n\n/**\n * 宿主 `ToolDefinition` 的结构子集。\n *\n * 刻意不 import 宿主的类型：`@deepseek-ai/dsh-tools` 在运行期由宿主提供，\n * 这里只描述「宿主会读哪些字段」，避免把插件绑死在某个宿主版本的类型上。\n */\nexport interface ImageToolDefinition {\n  readonly name: string\n  readonly description: string\n  readonly parameters: Record<string, unknown>\n  readonly output: {\n    readonly schema: Record<string, unknown>\n    render(args: unknown, value: unknown): ImageToolContentBlock[]\n  }\n  readonly timeoutMs: number\n  execute(args: unknown, exec: ImageToolExec): Promise<Record<string, unknown>>\n}\n\n/** 宿主传给 execute 的执行上下文里本工具用得到的部分。 */\nexport interface ImageToolExec {\n  readonly signal?: AbortSignal\n}\n\n/**\n * 选这次真正要用的模型。\n *\n * 优先级只有三级，且第二级「谁写的」决定写错了谁负责：\n *\n *   1. 调用方显式传的 `model`——写错就报错（`pickMediaModel` 会列出可用项）。\n *   2. 用户在卡片上选的偏好（`preferredImageModel`）——**只在没显式传时**生效，\n *      而且失效时静默回落，因为目录可能已经变过，一个过期偏好不该卡住一次生成。\n *   3. 组内第一个，也就是上游目录今天给的那条（默认 `hunyuan-image-alpha`）。\n *\n * 偏好只落在软约束这一侧，是因为它和 `model` 参数的区别是**谁写的**：参数是这次\n * 的调用者写的，偏好是用户上一次在卡片上点的。这与视频工具 `preferredVideoModel`\n * 的判据完全一致，两个工具不该有两套说法。\n */\nfunction resolveImageModel(\n  models: readonly WorkBuddyMediaModel[],\n  requested: string | undefined,\n  tag: string,\n  deps: ImageToolDeps,\n  credential: WorkBuddyCredential,\n  region: 'cn' | 'global',\n): WorkBuddyMediaModel {\n  // 可选集合 = 目录给的 + 本插件补的那条无水印模型（见 `imageModelChoices`）。\n  // 国际区拿不到它：实测 `hunyuan-image-v3.0` 在国际区直接 14401 route config\n  // not found，把它列进国际区的选项就是给一个点了必然失败的按钮。\n  const choices = region === 'cn'\n    ? imageModelChoices(models, tag)\n    : models.filter(model => model.tags.includes(tag))\n  const pinned = requested === undefined ? deps.preferredImageModel?.(credential, tag) : undefined\n  try {\n    return pickMediaModel(choices, requested ?? pinned, tag)\n  } catch (error: unknown) {\n    // 显式参数写错要原样抛；偏好过期则当作「没选」，回落组内第一个。\n    if (requested !== undefined || pinned === undefined) throw error\n    return pickMediaModel(choices, undefined, tag)\n  }\n}\n\n/** 工具运行所需的外部能力，全部由 `src/index.ts` 注入，便于单测替换。 */\nexport interface ImageToolDeps {\n  /** 解析生图所用区的凭据；该区未登录/未授权则返回 undefined（不要抛异常）。 */\n  readonly resolveCredential: () => Promise<WorkBuddyCredential | undefined>\n  /** 读该凭据所属区的产品配置，返回该区**全部**媒体模型（调用方按 tag 分组）。 */\n  readonly listMediaModels: (\n    credential: WorkBuddyCredential,\n    signal?: AbortSignal,\n  ) => Promise<readonly WorkBuddyMediaModel[]>\n  /**\n   * 该区在卡片上选定的文生图模型 id，没选就返回 undefined。\n   *\n   * 只在调用方没显式传 `model` 时生效。用它而不是在工具里硬编码「无水印模型」，\n   * 是因为这条例径有实打实的代价（单价 6 → 11.1 积分、尺寸上限从 419 万像素掉到\n   * 104 万），必须由用户自己选，工具不替他决定花更多钱。\n   */\n  readonly preferredImageModel?: (\n    credential: WorkBuddyCredential,\n    tag: string,\n  ) => string | undefined\n  /** 真正发一次文生图请求。 */\n  readonly generateImage: (\n    credential: WorkBuddyCredential,\n    request: { readonly model: string; readonly prompt: string; readonly size: string },\n    signal?: AbortSignal,\n  ) => Promise<WorkBuddyImageOutcome>\n  /** 真正发一次改图请求（输入图已是 data URL）。 */\n  readonly editImage: (\n    credential: WorkBuddyCredential,\n    request: {\n      readonly model: string\n      readonly prompt: string\n      readonly size: string\n      readonly image: readonly string[]\n    },\n    signal?: AbortSignal,\n  ) => Promise<WorkBuddyImageOutcome>\n  readonly logger: { warn(message: string): void }\n}\n\nfunction asRecord(value: unknown): Record<string, unknown> {\n  return typeof value === 'object' && value !== null ? value as Record<string, unknown> : {}\n}\n\nfunction asNonEmptyString(value: unknown): string | undefined {\n  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined\n}\n\n/**\n * 把工具参数 `image` 规整成输入图列表。\n *\n * 返回 undefined 表示「没给图」（文生图）；字符串数组 → 多张（上游\n * `/v2/images/edits` 的 `image` 字段本来就收数组）。\n *\n * 只收数组：一张图也写成 `[\"/abs/path.png\"]`。早先的 schema 是\n * `type: ['string', 'array']`，联合类型在只认单 type 的 function-calling 上游\n * 会被压平或整段丢掉，模型也会写出 `image: \"a.png\"` 这种半对半错的值；\n * 现在统一成数组，类型不对就明说，不去猜调用方想表达什么。\n *\n * 畸形输入（字符串 / 数字 / 对象 / 布尔、空数组，或数组里混了非字符串 / 空串）抛\n * INVALID_ARGS——绝不能像更早那样把「不是单个字符串」当「没给图」，那会让\n * 参考图被悄悄丢掉、工具静默退回文生图，生成的画面跟 prompt 毫无关系。\n */\nfunction asImageList(value: unknown): string[] | undefined {\n  if (value === undefined || value === null) return undefined\n  if (Array.isArray(value)) {\n    if (value.length === 0) {\n      throw inputImageError(\n        'workbuddy image: image 收到了空数组。纯文生图请把 image 字段整个省略，'\n        + '不要传 []；要改图就给至少一张，如 [\"/abs/a.png\"]。',\n      )\n    }\n    const items: string[] = []\n    for (const item of value) {\n      if (typeof item !== 'string' || item.trim() === '') {\n        throw inputImageError(\n          'workbuddy image: image 数组的每个元素都必须是非空字符串'\n          + '（本地路径 / file:// / http(s) / data URL / 裸 base64）。',\n        )\n      }\n      items.push(item.trim())\n    }\n    return items\n  }\n  if (typeof value === 'string') {\n    throw inputImageError(\n      `workbuddy image: image 必须是字符串数组，一张图也要写成数组。`\n      + `收到的是字符串 ${JSON.stringify(value.slice(0, 40))}，`\n      + `请改写成 [\"${value.slice(0, 40)}\"]。`,\n    )\n  }\n  throw inputImageError(\n    'workbuddy image: image 必须是字符串数组'\n    + '（如 [\"/abs/a.png\"] 或 [\"/abs/a.png\", \"/abs/b.png\"]），'\n    + '元素是本地路径 / file:// / http(s) / data URL / 裸 base64。',\n  )\n}\n\n/**\n * 可选字符串参数（size / model）：undefined/null/空串 → 未提供；其它类型\n * （数字 / 数组 / 对象 / 布尔）→ INVALID_ARGS。\n *\n * 旧行为把类型不对的值静默丢掉、回落到默认值：`model: [\"hy-image-3.0\"]`\n * 会安静地用默认模型扣积分，`size: 1024` 安静地用默认尺寸——与 image 数组\n * 被静默丢掉切回文生图是同一族错误，只是后果轻些。类型写错就明说，\n * 不要替调用方猜一个默认值。\n *\n * size 还要再过一道格式关（见 {@link parseSizeSpec}）：schema 里的 pattern\n * 只是给模型的提示，宿主不代校验，真正拦住「2K」「1024」「1024*1024」的是这里。\n */\nfunction strictString(value: unknown, name: string): string | undefined {\n  if (value === undefined || value === null) return undefined\n  if (typeof value !== 'string') {\n    throw inputImageError(\n      `workbuddy image: 参数 ${name} 必须是字符串（或不填），实际是`\n      + `${Array.isArray(value) ? '数组' : typeof value}。`,\n    )\n  }\n  return value.trim() === '' ? undefined : value.trim()\n}\n\n/** 「宽x高」——允许 `x` / `X` / 全角 `×`；不接受 `*`、空格、带单位。 */\nconst SIZE_PATTERN = /^[0-9]+[xX×][0-9]+$/\n/**\n * 上游实测上限：总像素约 419 万（见 docs/IMAGE_GEN.md「尺寸与比例」）。\n *\n * 这是**默认档**（`hunyuan-image-alpha` 那一族）的数字。真正生效的范围由\n * {@link ImageSizePlan} 一路传下来的 `WorkBuddyImageSizeLimits` 决定——v3.0 的\n * 边更短、像素更少（见 `imageSizeLimitsOf`）。这里的常量只是那个函数的缺省值，\n * 不是「所有模型的边界」。\n */\nconst MAX_IMAGE_PIXELS = IMAGE_SIZE_LIMITS_WIDE.maxPixels\n/** 边长支持范围。上限 2560 来自实测通过的最大长边（2560x1440 / 2560x1600）。 */\nconst MIN_IMAGE_EDGE = IMAGE_SIZE_LIMITS_WIDE.minEdge\nconst MAX_IMAGE_EDGE = IMAGE_SIZE_LIMITS_WIDE.maxEdge\n/** 实测被上游拒绝的尺寸，报错时直接点出来，省得模型反复试。 */\nconst KNOWN_BAD_SIZES: ReadonlySet<string> = new Set(['2560x2560', '3072x3072', '4096x4096'])\n\n/** 本工具真正认的参数——与 `parameters.properties` 一一对应。 */\nconst ALLOWED_ARGS: ReadonlySet<string> = new Set(['prompt', 'size', 'image', 'model'])\n\n/**\n * 拒掉 schema 里没有的参数。\n *\n * `additionalProperties: false` 只是写在 schema 里给模型看的，宿主把\n * `parameters` 原样投影、不代校验，execute 照样会收到 `ratio: '16:9'` 这种\n * 从别的生图工具（agnes 那边就叫 ratio / n / return_base64）串过来的字段。\n * 静默忽略的后果是模型以为改的比例生效了、其实出的是默认方图，所以这里明说。\n */\nfunction rejectUnknownArgs(record: Record<string, unknown>): void {\n  const unknown = Object.keys(record).filter(key => !ALLOWED_ARGS.has(key))\n  if (unknown.length === 0) return\n  throw inputImageError(\n    `workbuddy image: 本工具没有 ${unknown.map(key => `「${key}」`).join('、')} 参数，`\n    + '只有 prompt、size、image、model 四个。'\n    + '比例 / 横竖用 size 的「宽x高」（size 必填）；要几张图就调用几次（一次一张）。',\n  )\n}\n\n/**\n * 解析 size：必填、必须写成「宽x高」或 `auto`。\n *\n * **必填**是因为以前不填就静默按 1024x1024 出方图，模型于是学会了「什么都不写、\n * 让它自己猜」——要竖版壁纸也出方图，用户还看不出是哪一步丢的。\n *\n * 这里只管**格式**，不管范围：越界不报错，交给 {@link planImageSize} 等比收进\n * 范围（那条路要等输入图量过宽高，见那边的说明）。\n *\n * `parameters.pattern` 只是写给模型看的，宿主把 `parameters` 原样投影、不代校验，\n * execute 收到的可能是 `\"2K\"` / `1024`（已由 {@link strictString} 拦下）/ `\"1024*1024\"`。\n * 这些猜不出调用方到底想要多大的输入仍然直接 INVALID_ARGS（本地免费）。\n */\nfunction parseSizeSpec(value: unknown): SizeSpec {\n  const raw = strictString(value, 'size')\n  if (raw === undefined) {\n    throw inputImageError(\n      'workbuddy image: 参数 size 必填，写成「宽x高」的像素数，改图也可以写 auto。'\n      + '方图 1024x1024、竖图 1024x1536、横图 1536x1024、16:9 桌面 2560x1440、'\n      + '9:16 手机壁纸 1440x2560。比例由它决定，不填不会替你猜。',\n    )\n  }\n  const normalized = raw.toLowerCase()\n  if (normalized === 'auto') return { kind: 'auto' }\n  if (!SIZE_PATTERN.test(normalized)) {\n    throw inputImageError(\n      `workbuddy image: 参数 size 必须写成「宽x高」的像素数或 auto，收到的是 ${JSON.stringify(raw)}。`\n      + '例如 1024x1024（方图）、1024x1536（竖图）、1536x1024（横图）、2560x1440（16:9）。'\n      + '不要写「2K」「4K」「高清」这类档位，也不要只写一个边长。',\n    )\n  }\n  // 走到这里 pattern 已经命中，两段一定存在；给默认值是为了让类型系统也同意\n  // （tsconfig 开了 noUncheckedIndexedAccess），空串经 Number 变成 0 会被下面的闸门拦下。\n  const [widthPart = '', heightPart = ''] = normalized.split(/[xX×]/)\n  const width = Number(widthPart)\n  const height = Number(heightPart)\n  if (!Number.isInteger(width) || !Number.isInteger(height) || width < 1 || height < 1) {\n    throw inputImageError(\n      `workbuddy image: 参数 size 的宽高必须是正整数，收到的是 ${JSON.stringify(raw)}。`,\n    )\n  }\n  return { kind: 'fixed', width, height, normalized }\n}\n\n/**\n * 把解析好的尺寸规格落成一个真正要发给上游的值。\n *\n * 与 {@link parseSizeSpec} 分开，是因为这两件事的**时机**不同：格式错误要在收到\n * 参数的第一时间就报（本地免费），而 `auto` 与越界缩放都要等输入图量过宽高、\n * 也要等**模型定下来**——两个模型的合法范围不一样（见 `imageSizeLimitsOf`）。\n *\n * 越界为什么由工具收、而不是让模型自己算：两条边（512–2560）与总像素\n * （≤4,194,304）是两个约束，手算要取「2560/长边」与「√(4194304/面积)」里更小的\n * 那个**再复查一遍**。要求模型在参数里做这种算术，实测会算出仍然越界的值\n * （2480x3508 → 1810x2560，边长合规但乘积 4,633,600 仍超）。收完之后把「动过什么」\n * 写进 hint，模型得据实转告用户，不能假装按用户给的尺寸出图。\n *\n * `limits` 来自**这一次选中的模型**，不是全局常量：v3.0 的边更短、像素更少，\n * 用 alpha 的范围替它算会得到上游 400（实测 `1024x1025` 就被拒）。\n */\n/**\n * `size: auto` 但量不出输入图 —— 这一步**不需要模型**，所以单独提出来。\n *\n * 报错时机是这里唯一的理由：模型的失败（目录里没这条模型）要花一次目录请求\n * 才能知道，而「你写了 auto 却没给图」在本地就能判。把它压到模型解析之后，\n * 一个纯参数错误就会被「目录里没有模型」盖掉，用户改完一处还得再撞第二处。\n */\nfunction missingAutoSizeInput(): never {\n  throw inputImageError(\n    'workbuddy image: size 写了 auto，但这一次量不出输入图的宽高'\n    + '（没有给 image，或给的图格式认不出来），没法替你挑画布。'\n    + '请直接写具体尺寸：方图 1024x1024、竖图 1024x1536、横图 1536x1024。',\n  )\n}\n\n/** `auto` 必须配一张量得出宽高的图；没有就报那条错误，否则原样返回。 */\nfunction requireAutoInput(input: ImageDimensions | undefined): ImageDimensions {\n  return input ?? missingAutoSizeInput()\n}\n\nfunction planImageSize(\n  spec: SizeSpec,\n  input: ImageDimensions | undefined,\n  limits: WorkBuddyImageSizeLimits,\n): SizePlan {\n  if (spec.kind === 'auto') {\n    // 调用方（execute）已经在解析模型之前拦过「auto 却没有图」；\n    // 这里再判一次是为了让函数自己不依赖调用顺序，绝不静默挑一个画布。\n    const source = requireAutoInput(input)\n    const canvas = canvasForInput(source, limits)\n    const size = `${canvas.width}x${canvas.height}`\n    return {\n      size,\n      requested: 'auto',\n      note: canvas.exact\n        ? `size 写的是 auto，已按输入图 ${source.width}x${source.height} 的比例取画布 `\n          + `${size}（${ORIENTATION_LABEL[orientationOf(source)]}）`\n        : `输入图 ${source.width}x${source.height} 太细长，等比缩不出合法的画布，`\n          + `已改用${ORIENTATION_LABEL[orientationOf(source)]}常用档 ${size}，比例有变化`,\n    }\n  }\n  const { width, height, normalized } = spec\n  if (isSizeInRange(width, height, normalized, limits)) return { size: `${width}x${height}` }\n\n  const fitted = fitIntoRange(width, height, limits)\n  if (fitted === undefined) {\n    throw inputImageError(\n      `workbuddy image: 参数 size ${normalized} 的比例太极端，等比缩放放不进 `\n      + `${describeLimits(limits)} 的范围内。`\n      + '请改成接近的常用档位：'\n      + sampleSizesFor(limits)\n      + '。',\n    )\n  }\n  const direction = fitted.direction === 'up' ? '放大' : '缩小'\n  return {\n    size: `${fitted.width}x${fitted.height}`,\n    requested: normalized,\n    note: `你给的尺寸 ${normalized} 超出${describeLimits(limits)}，`\n      + `已等比${direction}到 ${fitted.width}x${fitted.height}`,\n  }\n}\n\n/**\n * 一句话说清这次的上限，用在两条错误/提示里。\n *\n * 说「419 万」而不是「4,194,304」：hint 是要模型原样转述给用户的，像素数写全\n * 数字没人读得进去，而「约 419 万像素」既准确又够用。v3.0 的 104 万同理\n * （1048576/1e4 = 104.9 → 105，不是 1）。\n */\nfunction describeLimits(limits: WorkBuddyImageSizeLimits): string {\n  const wan = (limits.maxPixels / 10_000).toFixed(0)\n  return ` ${limits.minEdge}–${limits.maxEdge} 边长或约 ${wan} 万像素上限`\n}\n\n/** 这个范围内拿得出手的档位例子——按半径给出，别举一个会被拒的。 */\nfunction sampleSizesFor(limits: WorkBuddyImageSizeLimits): string {\n  if (limits.maxPixels <= 1_048_576) {\n    return '方图 1024x1024、竖图 768x1024、横图 1280x720'\n  }\n  return '方图 1024x1024、竖图 1024x1536、横图 1536x1024、16:9 桌面 2560x1440、9:16 手机壁纸 1440x2560'\n}\n\n/**\n * 这些失败说明请求真的打到了上游、可能已经扣了积分，才值得进冷却。\n * 参数写错 / 未登录 / 目录里没有模型都还没花钱。\n */\n/**\n * 这些失败码都发生在「请求已经发出去」之后——上游可能已经扣了积分或排了队，\n * 连续重试只会把它们再花一遍，所以进冷却。\n */\nconst BILLABLE_FAILURE_CODES: ReadonlySet<string> = new Set([\n  'AUTH',\n  'RATE_LIMIT',\n  'NO_ROUTE',\n  'UPSTREAM',\n  'EMPTY_RESULT',\n])\n\n/**\n * 是否该进冷却——由「这一次到底有没有把生图请求发出去」决定，而不是由异常\n * 的类型反推。\n *\n * 早先的写法是「不是 WorkBuddyImageError 就算花过钱」，方向正好错了两头：\n * 读目录（`fetchMediaModels` 的那次只读 GET）失败抛的是 upstream.ts 的\n * `envelopeError`/网络错误，一分钱没花却把工具冷却 30 秒；而参数写错这类真正\n * 免费的失败又因为带着 `INVALID_ARGS` 才被放行——判据和事实不在一根轴上。\n *\n * 现在由调用点显式置位：请求发出去了才置 `sent`，冷却只看它。\n */\nfunction isBillableFailure(error: unknown, sent: boolean): boolean {\n  if (!sent) return false\n  if (error instanceof WorkBuddyImageError) return BILLABLE_FAILURE_CODES.has(error.code)\n  // 请求已发出之后的意外异常（读响应体时连接断了等）同样算一次真实尝试。\n  return true\n}\n\n/** 生成图片的临时目录（issue #174）——清理由 {@link pruneTempDir} 负责。 */\nconst TEMP_IMAGE_DIR = join(tmpdir(), 'workbuddy-image-gen')\n\n/** 把 b64 图片落成一个临时文件，返回绝对路径。 */\nasync function writeTempImage(b64: string, model: string): Promise<string> {\n  await mkdir(TEMP_IMAGE_DIR, { recursive: true })\n  const stamp = new Date().toISOString().replace(/[:.]/g, '-')\n  const safeModel = model.replace(/[^A-Za-z0-9._-]+/g, '_')\n  const path = join(TEMP_IMAGE_DIR, `${safeModel}-${stamp}.png`)\n  await writeFile(path, Buffer.from(b64, 'base64'))\n  // 机会式清理（issue #174）：在写入之后跑，不 await——回给模型的是路径，不是清理\n  // 报告，而清理失败不该让一次成功的生成变成失败。`void` 而不是裸调用，是为了让\n  // 「这是故意不等」一眼能看出来。\n  void pruneTempDir(TEMP_IMAGE_DIR, TEMP_MEDIA_KEEP, ['.png'])\n  return path\n}\n\n/**\n * 输入图的一切毛病都发生在「请求还没发出去」之前，所以统一用 INVALID_ARGS：\n * 不进冷却、不花积分，错误信息直接说清是哪个环节。\n */\nfunction inputImageError(message: string): WorkBuddyImageError {\n  return new WorkBuddyImageError(message, 'INVALID_ARGS')\n}\n\nconst INLINE_BASE64_LABEL = '（内联 base64）'\nconst INLINE_DATA_URL_LABEL = '（内联 data URL）'\n\n/** 图片的像素宽高。 */\ninterface ImageDimensions {\n  readonly width: number\n  readonly height: number\n}\n\n/** 输入图的朝向——改图时用它给输出画布挑档。 */\ntype ImageOrientation = 'landscape' | 'portrait' | 'square'\n\n/** 方图容差：长短边之差不到长边的 5% 就算方图（比如 1000x1010）。 */\nconst SQUARE_TOLERANCE = 0.05\n\nconst ORIENTATION_LABEL: Readonly<Record<ImageOrientation, string>> = {\n  landscape: '横图',\n  portrait: '竖图',\n  square: '方图',\n}\n\n/** `size: \"auto\"` 的输出长边：够 1080P 用，又离 419 万像素上限还远。 */\nconst AUTO_LONG_EDGE = 1536\n\n/** 方向兜底档位：改图写了 auto 但比例极端到算不出画布、或干脆量不出宽高时用。 */\nconst DEFAULT_SIZE_BY_ORIENTATION: Readonly<Record<ImageOrientation, ImageDimensions>> = {\n  landscape: { width: 1536, height: 1024 },\n  portrait: { width: 1024, height: 1536 },\n  square: { width: 1024, height: 1024 },\n}\n\n/**\n * 从图片字节里读像素宽高。\n *\n * 为什么值得自己解析：改图时 `size` 是**输出画布**，最合理的默认值由输入图的\n * 方向决定；但上游不回传输入尺寸，模型也读不到本地文件。早几版的描述要求模型\n * 「按原图比例挑一档」——那是在要求它猜，两个评审子代理都判这条不可执行。\n * 现在在把输入图读成字节的同一处顺手解出宽高，模型直接被告知真实方向。\n *\n * 只读文件头里的两个整数：不解码像素、不校验 CRC。认不出（或头不完整）就返回\n * undefined，让调用方退回方向兜底——「量不出尺寸」不该变成一次失败。\n *\n * 覆盖 PNG（IHDR）、JPEG（任一 SOF 段）、GIF（逻辑屏幕描述符）、WEBP\n * （VP8 / VP8L / VP8X 三种子格式）。\n */\nfunction parseImageDimensions(bytes: Uint8Array): ImageDimensions | undefined {\n  const at = (index: number): number => bytes[index] ?? 0\n  const u16be = (index: number): number => (at(index) << 8) | at(index + 1)\n  const u16le = (index: number): number => at(index) | (at(index + 1) << 8)\n  const u24le = (index: number): number => at(index) | (at(index + 1) << 8) | (at(index + 2) << 16)\n  const u32be = (index: number): number =>\n    at(index) * 0x1000000 + (at(index + 1) << 16) + (at(index + 2) << 8) + at(index + 3)\n  const u32le = (index: number): number =>\n    (at(index) | (at(index + 1) << 8) | (at(index + 2) << 16)) + at(index + 3) * 0x1000000\n  const positive = (width: number, height: number): ImageDimensions | undefined =>\n    width > 0 && height > 0 ? { width, height } : undefined\n\n  // PNG：8 字节签名 + IHDR 长度/类型，宽高是紧跟其后的两个大端 32 位。\n  if (bytes.length >= 24\n    && at(0) === 0x89 && at(1) === 0x50 && at(2) === 0x4e && at(3) === 0x47) {\n    return positive(u32be(16), u32be(20))\n  }\n\n  // JPEG：段链扫描，第一个 SOFn 段里 precision(1) + height(2) + width(2)。\n  if (at(0) === 0xff && at(1) === 0xd8) {\n    let offset = 2\n    while (offset + 8 < bytes.length) {\n      if (at(offset) !== 0xff) {\n        offset += 1\n        continue\n      }\n      const marker = at(offset + 1)\n      // 无长度的独立标记：TEM、RSTn、SOI。\n      if (marker === 0x01 || marker === 0xd8 || (marker >= 0xd0 && marker <= 0xd7)) {\n        offset += 2\n        continue\n      }\n      const length = u16be(offset + 2)\n      if (length < 2) return undefined\n      const isSof = marker >= 0xc0 && marker <= 0xcf\n        && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc\n      if (isSof) return positive(u16be(offset + 7), u16be(offset + 5))\n      offset += 2 + length\n    }\n    return undefined\n  }\n\n  // GIF：逻辑屏幕描述符在偏移 6，宽高各 2 字节小端。\n  if (at(0) === 0x47 && at(1) === 0x49 && at(2) === 0x46) {\n    return positive(u16le(6), u16le(8))\n  }\n\n  // WEBP：RIFF....WEBP + 子块。三种子格式的宽高位置都不一样。\n  if (bytes.length >= 30\n    && at(0) === 0x52 && at(1) === 0x49 && at(2) === 0x46 && at(3) === 0x46\n    && at(8) === 0x57 && at(9) === 0x45 && at(10) === 0x42 && at(11) === 0x50) {\n    const chunk = String.fromCharCode(at(12), at(13), at(14), at(15))\n    if (chunk === 'VP8 ') {\n      // 有损：3 字节帧标签 + 3 字节起始码 9d 01 2a，随后是 14 位宽、14 位高。\n      if (at(23) !== 0x9d || at(24) !== 0x01 || at(25) !== 0x2a) return undefined\n      return positive(u16le(26) & 0x3fff, u16le(28) & 0x3fff)\n    }\n    if (chunk === 'VP8L') {\n      // 无损：签名 0x2f 之后 14 位宽-1、14 位高-1。\n      const bits = u32le(21)\n      return positive((bits & 0x3fff) + 1, ((bits >> 14) & 0x3fff) + 1)\n    }\n    if (chunk === 'VP8X') {\n      // 扩展：1 字节标志 + 3 字节保留，随后 24 位宽-1、24 位高-1。\n      return positive(u24le(24) + 1, u24le(27) + 1)\n    }\n    return undefined\n  }\n\n  return undefined\n}\n\n/** 由宽高判方向——改图据此挑输出画布。 */\nfunction orientationOf(dimensions: ImageDimensions): ImageOrientation {\n  const longest = Math.max(dimensions.width, dimensions.height)\n  const shortest = Math.min(dimensions.width, dimensions.height)\n  if (longest - shortest <= longest * SQUARE_TOLERANCE) return 'square'\n  return dimensions.width > dimensions.height ? 'landscape' : 'portrait'\n}\n\n/**\n * 取第一张**量得出宽高**的输入图的尺寸。\n *\n * 用第一张不是因为「第一张最重要」，而是因为多张横竖混用时必须有个确定的判据：\n * 描述里已经写着「多张按第一张定」，这里就跟它对齐。第一张解析不出来就顺延到\n * 下一张，总比直接放弃好——认不出格式的图（比如上游还没见过的）不该让整次改图\n * 失去参照。\n */\nfunction firstDimensions(\n  inputs: readonly { readonly dimensions?: ImageDimensions }[],\n): ImageDimensions | undefined {\n  for (const input of inputs) {\n    if (input.dimensions !== undefined) return input.dimensions\n  }\n  return undefined\n}\n\n/**\n * 按输入图的比例定输出画布（`size: \"auto\"`）。\n *\n * 长边固定 {@link AUTO_LONG_EDGE}、短边同比算——这是「改图别改版式」的落点：模型\n * 看不到原图多大，让它自己按比例挑档等于让它猜（1600x900 该写 2560x1440 还是\n * 1536x864？）。方图走 1024x1024：1536x1536 会顶到 235 万像素，比上游常用档大，\n * 方图的短边也没有信息增益。\n *\n * 极端比例（比 5:1 还细长）等比缩放放不进范围时，退回按方向的常用档——宁可换\n * 比例，也不能报错让用户无从下手；`exact: false` 就是用来把这句实话写进 hint 的。\n */\nfunction canvasForInput(\n  input: ImageDimensions,\n  limits: WorkBuddyImageSizeLimits,\n): { readonly width: number; readonly height: number; readonly exact: boolean } {\n  const orientation = orientationOf(input)\n  if (orientation === 'square') return { ...DEFAULT_SIZE_BY_ORIENTATION.square, exact: true }\n  const longest = Math.max(input.width, input.height)\n  const shortest = Math.min(input.width, input.height)\n  const short = Math.max(1, Math.round((shortest * AUTO_LONG_EDGE) / longest))\n  const width = orientation === 'landscape' ? AUTO_LONG_EDGE : short\n  const height = orientation === 'landscape' ? short : AUTO_LONG_EDGE\n  if (isSizeInRange(width, height, `${width}x${height}`, limits)) {\n    return { width, height, exact: true }\n  }\n  const fitted = fitIntoRange(width, height, limits)\n  if (fitted !== undefined) return { width: fitted.width, height: fitted.height, exact: true }\n  return { ...DEFAULT_SIZE_BY_ORIENTATION[orientation], exact: false }\n}\n\n/** 两个上限（长边 2560、总像素 419 万）同时满足时，把宽高按比例收进范围。 */\nfunction shrinkProduct(\n  width: number,\n  height: number,\n  limits: WorkBuddyImageSizeLimits,\n): ImageDimensions {\n  let w = width\n  let h = height\n  // 各自 floor 之后乘积仍可能略超上限（2509x1673 = 4,197,557），再收一两轮即可，\n  // 循环上限只是防御——正常情况下第二轮就到位。\n  for (let round = 0; round < 4 && w * h > limits.maxPixels; round += 1) {\n    const scale = Math.sqrt(limits.maxPixels / (w * h))\n    w = Math.floor(w * scale)\n    h = Math.floor(h * scale)\n  }\n  return { width: w, height: h }\n}\n\n/**\n * 把一个越界尺寸等比缩/放到合法范围。\n *\n * 两条边（512–2560）与总像素（≤4,194,304）是两个约束，必须同时满足：只按长边缩\n * 会把 2480x3508 变成 1810x2560（边长都对、乘积 4,633,600 仍越界）。所以缩放比取\n * 「2560/长边」与「√(4194304/(宽×高))」里更小的那个。\n *\n * 返回 undefined 表示等比缩放解不出来（比例比 5:1 还极端：缩到长边 2560 时短边\n * 已经小于 512，抬到 512 时长边又超过 2560），交给调用方按方向换档。\n */\nfunction fitIntoRange(\n  width: number,\n  height: number,\n  limits: WorkBuddyImageSizeLimits,\n): { readonly width: number; readonly height: number; readonly direction: 'down' | 'up' } | undefined {\n  const { minEdge, maxEdge, maxPixels } = limits\n  const longest = Math.max(width, height)\n  const shortest = Math.min(width, height)\n  const tooBig = longest > maxEdge || width * height > maxPixels\n  const tooSmall = shortest < minEdge\n\n  if (!tooBig && tooSmall) {\n    // 只小不大：短边抬到 minEdge，另一边同比放大。长边放大后若超上限就交给下面的兜底。\n    const scale = minEdge / shortest\n    if (longest * scale <= maxEdge) {\n      const scaled = shrinkProduct(Math.round(width * scale), Math.round(height * scale), limits)\n      return { ...scaled, direction: 'up' }\n    }\n    return undefined\n  }\n\n  const scale = Math.min(maxEdge / longest, Math.sqrt(maxPixels / (width * height)))\n  const scaled = shrinkProduct(Math.floor(width * scale), Math.floor(height * scale), limits)\n  if (scaled.width >= minEdge && scaled.height >= minEdge) {\n    return { ...scaled, direction: 'down' }\n  }\n\n  // 极端比例：短边缩到 minEdge 之后长边仍然超上限，等比缩放无解。\n  const extreme = minEdge / shortest\n  if (longest * extreme <= maxEdge) {\n    const lifted = shrinkProduct(Math.round(width * extreme), Math.round(height * extreme), limits)\n    if (lifted.width * lifted.height <= maxPixels) return { ...lifted, direction: 'up' }\n  }\n  return undefined\n}\n\n/** 解析后的尺寸参数：`auto` 或一个具体的像素尺寸。 */\ntype SizeSpec =\n  | { readonly kind: 'auto' }\n  | {\n    readonly kind: 'fixed'\n    readonly width: number\n    readonly height: number\n    /** 小写规整后的原值，报错与 hint 都用它。 */\n    readonly normalized: string\n  }\n\n/** 尺寸的最终决定：发给上游的值、用户原本写的值、以及「动过什么」的说明。 */\ninterface SizePlan {\n  /** 最终发给上游的尺寸，小写「宽x高」。 */\n  readonly size: string\n  /** 规整成小写后的原始输入；写了 auto 就是 'auto'，没动过尺寸时不回带。 */\n  readonly requested?: string\n  /** 对尺寸做过什么，原样写进 hint——模型得据实转告用户。 */\n  readonly note?: string\n}\n\n/**\n * 一个尺寸能否**原样**发给这次选中的模型。\n *\n * 三个判据都跟着 `limits` 走，不是全局常量：v3.0 的边 2048 / 像素 1,048,576，\n * alpha 才是 2560 / 4,194,304。`KNOWN_BAD_SIZES` 是那个宽档下实测被拒的档位，\n * 窄档的边界由 `limits` 本身就够判，不必再叠一份。\n */\nfunction isSizeInRange(\n  width: number,\n  height: number,\n  normalized: string,\n  limits: WorkBuddyImageSizeLimits,\n): boolean {\n  if (KNOWN_BAD_SIZES.has(normalized)) return false\n  if (width < limits.minEdge || height < limits.minEdge) return false\n  if (width > limits.maxEdge || height > limits.maxEdge) return false\n  return width * height <= limits.maxPixels\n}\n\n/**\n * 体积与空文件闸门——四种输入形态都从这里过，所以「空文件」和「超过 8 MB」的\n * 文案只有一份。\n *\n * `byteLength` 必须是**解码后**的字节数：base64 比原始字节长约 4/3，拿字符串长度\n * 比上限度会把一个 6 MB 的图误判成超限（并在错误信息里报出一个虚高的 MB 数）。\n */\nfunction assertInputImageBytes(byteLength: number, source: string): void {\n  if (byteLength === 0) throw inputImageError(`workbuddy image: 输入图是空文件：${source}`)\n  if (byteLength > MAX_INPUT_IMAGE_BYTES) {\n    const limit = MAX_INPUT_IMAGE_BYTES / 1024 / 1024\n    const actual = (byteLength / 1024 / 1024).toFixed(1)\n    throw inputImageError(`workbuddy image: 输入图 ${actual} MB，超过 ${limit} MB 上限：${source}`)\n  }\n}\n\n/**\n * 把任意形态的输入图规整成上游唯一接受的形态：`data:<mime>;base64,<b64>`。\n *\n * 官方 CLI 的 `processImageInput` 收 data URL、http(s)、裸 base64、本地路径四\n * 种；这里只是把前三种归一，**不做**缩放、裁剪、格式转换——用户给什么就传什么，\n * 免得悄悄改了输入图。\n */\nasync function resolveImageInput(\n  value: string,\n  signal?: AbortSignal,\n): Promise<ResolvedImageInput> {\n  const text = value.trim()\n  if (text.startsWith('data:')) {\n    const parsed = parseImageDataUrl(text)\n    if (parsed === undefined) {\n      throw inputImageError(\n        'workbuddy image: image 看起来是 data URL，但格式不对（需要 data:image/*;base64,...）。',\n      )\n    }\n    // 这一支以前直接 return，于是绕过了 encodeInputImage 里的空文件与 8 MB 闸门：\n    // 一个超限的 data URL 会原样发给上游，失败后还会按「请求已发出」进 30 秒冷却\n    // ——正是「输入图的毛病都该在请求发出前报 INVALID_ARGS」要避免的那种情形。\n    // 体积要按**解码后**的字节数算（base64 比原始字节长约 4/3），不能拿字符串长度比。\n    const bytes = Buffer.from(parsed.base64, 'base64')\n    assertInputImageBytes(bytes.byteLength, INLINE_DATA_URL_LABEL)\n    const dimensions = parseImageDimensions(new Uint8Array(bytes))\n    return dimensions === undefined ? { dataUrl: text } : { dataUrl: text, dimensions }\n  }\n  if (/^https?:\\/\\//i.test(text)) {\n    let response: Response\n    try {\n      response = await fetch(text, { signal: signal ?? AbortSignal.timeout(IMAGE_INPUT_TIMEOUT_MS) })\n    } catch (error: unknown) {\n      throw inputImageError(\n        `workbuddy image: 下载输入图失败（${text}）：`\n        + (error instanceof Error ? error.message : String(error)),\n      )\n    }\n    if (!response.ok) {\n      throw inputImageError(`workbuddy image: 下载输入图失败（HTTP ${response.status}）：${text}`)\n    }\n    return encodeResolvedImage(\n      new Uint8Array(await response.arrayBuffer()),\n      response.headers.get('content-type') ?? undefined,\n      text,\n    )\n  }\n  if (isBareBase64Image(text)) {\n    return encodeResolvedImage(\n      new Uint8Array(Buffer.from(text, 'base64')),\n      undefined,\n      INLINE_BASE64_LABEL,\n    )\n  }\n  const path = text.startsWith('file:') ? fileURLToPath(text) : text\n  let bytes: Buffer\n  try {\n    bytes = await readFile(path)\n  } catch (error: unknown) {\n    throw inputImageError(\n      `workbuddy image: 读不到输入图「${path}」：`\n      + (error instanceof Error ? error.message : String(error)),\n    )\n  }\n  return encodeResolvedImage(new Uint8Array(bytes), undefined, path)\n}\n\n/** 归一后的输入图：上游要的 data URL，加上顺手量到的像素宽高。 */\ninterface ResolvedImageInput {\n  readonly dataUrl: string\n  /** 量不出（格式不认识、头不完整）时没有这个字段；不影响这次请求。 */\n  readonly dimensions?: ImageDimensions\n}\n\n/** 校验体积、定出 mime，把字节编成 data URL，并顺手量宽高。 */\nfunction encodeResolvedImage(\n  bytes: Uint8Array,\n  contentType: string | undefined,\n  source: string,\n): ResolvedImageInput {\n  assertInputImageBytes(bytes.byteLength, source)\n  const declared = contentType?.split(';')[0]?.trim().toLowerCase()\n  const mime = declared !== undefined && declared.startsWith('image/')\n    ? declared\n    : imageMimeForPath(source) ?? sniffImageMime(bytes)\n  const dataUrl = imageDataUrl(mime, Buffer.from(bytes).toString('base64'))\n  const dimensions = parseImageDimensions(bytes)\n  // 量不出来就不带这个字段（exactOptionalPropertyTypes）：undefined 与「没有」\n  // 在类型上要一致，免得调用方用 `'dimensions' in input` 时得到两种含义。\n  return dimensions === undefined ? { dataUrl } : { dataUrl, dimensions }\n}\n/**\n * 造出工具定义。\n *\n * 每次 `apply()` 只造一个实例，所以冷却状态与目录缓存都挂在闭包里，\n * 生命周期跟着插件走。\n */\nexport function createImageTool(deps: ImageToolDeps): ImageToolDefinition {\n  let mediaCache: { readonly at: number; readonly models: readonly WorkBuddyMediaModel[] } | undefined\n  let cooldownUntil = 0\n\n  const listModels = async (\n    credential: WorkBuddyCredential,\n    signal?: AbortSignal,\n  ): Promise<readonly WorkBuddyMediaModel[]> => {\n    const now = Date.now()\n    if (mediaCache !== undefined && now - mediaCache.at < MEDIA_MODEL_TTL_MS) return mediaCache.models\n    const models = await deps.listMediaModels(credential, signal)\n    mediaCache = { at: now, models }\n    return models\n  }\n\n  return {\n    name: WORKBUDDY_IMAGE_TOOL_NAME,\n    description:\n      // 分段用 \\n：这段文字是模型唯一的说明书，挤成一整段时尺寸规则会被淹掉。\n      '用 WorkBuddy 生图或改图：一次调用只出一张图，要几张就调几次，每张单独计费。'\n      + '本工具没有 seed、不存历史、不能重放：同一段 prompt 重调不保证张张一样。'\n      + '所以先判一件事，跟要几张无关——用户要的是「一样」还是「不同」：'\n      + '(i) 要「一样」「同款」「同一张」「复制几张」「跟上一张一样」→ 做不到，说明原因，让他只出一张自己复制；不报价、不调用。要几张「都一样」就走这一条，不是「出 N 张」。'\n      + '(ii) 要「不同风格」「各来一张」→ 按 (b) 的口径报张数和总价（「4 张：国内版约 22.8、国际版约 0.12 积分」）→ 等他明确同意 → 连着调 N 次，每次换 prompt（换姿态、视角、光位）。'\n      + '(iii) 要「挑一张」「先看一张」→ 先出 1 张给他看，满意再按张补后面的，补之前重新报一次总价。'\n      + '没说同异、只问张数价钱（「4 张要多少钱」）→ 先问「要一样的还是各不相同的」，问完再报。'\n      + '这三条用 (i)(ii)(iii) 编号，(d) 里的 ①②③④⑤⑥⑦⑧ 是 size 的台阶，两套编号别混。'\n      + '什么时候必须先停下等用户点头，只看这七条：要出超过一张、这次调用会改变原图版式（裁切/留白）、'\n      + '文生图且主体还没定、用户把某个超过 2560 的像素当验收标准（原话里有「必须」「正好」「就是要」「不能改」）、'\n      + '用户要求硬排除某个元素（「绝对不能有 XX」）、要自己按表外比例算像素（见 ⑥）、'\n      + '用户本轮或上一轮里说过嫌贵、或正要你改区设置（(c)）。'\n      + '七条都不成立（单张文生图、size 用现成档位）就直接调，不用等点头；但单张仍要按 (b) 报一次两档价——那是告知，不是请示。'\n      + '成立两条以上时合成一次问完。'\n      + '「同意」只算用户明确说同意，沉默、反问、换话题都不算。'\n      + '\\n'\n      + '(a) 画什么：prompt 写主体、风格、构图、光线。用户给了主体、只是没给风格和光线，就由你补，别为这个反问他；'\n      + '只有 text-to-image 才受这条限制：用户连主体都没给（只说了尺寸、比例、档位、用途、方向或风格）就先问「想画什么」，'\n      + '不要自己编一个主体去扣积分。改图（给了 image）不算没主体——参考图本身就是主体，别拿着图还问「想画什么」。'\n      + '主体＝画面上要出现的人、物、景（「一只猫」「一束向日葵」）；只说「主题」「氛围」「风格」不算给了主体'\n      + '（「秋季新品」是主题，「一束向日葵」才是主体）；风格、流派、季节、情绪只说明怎么画，不说明画什么'\n      + '（「赛博朋克」「极简」「水彩」「秋天」「高级感」都不算主体）。'\n      + '可以写「不要出现